pub const E0002: Code = Code(&Entry { code: "E0002", title: "unexpected character", reference: "lexical.whitespace", rule: "Whitespace is space, tab and newline. Tabs are allowed, and `stilt fmt` replaces them (syntax.format.indentation). Outside string literals and comments, a character that is neither whitespace nor part of a token is E0002, unexpected character. Such characters include a form feed, a vertical tab, a no-break space, a letter outside ASCII, `~`, `\\`, a backtick and `×`.", tier: "core", phase: "syntax", help: "Outside strings and comments, Stilt reads only ASCII, so a curly quote or a symbol pasted from a document isn't code. Retype it, or put it inside a string.", span: "The unexpected character.", retired: false, examples: &[Example { wrong: "fn main() / io {\n  print(“hello”)\n}\n", line: 2, right: "fn main() / io {\n  print(\"hello\")\n}\n" }] });
