/// malformed number literal
pub const E0004: Code = Code(&Entry { code: "E0004", title: "malformed number literal", reference: "lexical.integer-literals", rule: "A decimal integer literal is `0`, or a nonzero digit followed by digits. The prefixes `0x` (hexadecimal), `0o` (octal) and `0b` (binary) give the other bases. A prefix is lowercase, and must be followed by at least one digit of its base. Hexadecimal digits may be either case. `_` may appear only between two digits. A decimal literal with a leading zero, such as `007` or `00`, is malformed. So is a number literal directly followed by a letter, a digit or `_`, as in `10u8`, `1e`, `0b102` or `0o8`: there are no type suffixes. A malformed number literal, integer or float, is E0004, malformed number literal, at the first character at which it breaks its grammar.", tier: "core", phase: "syntax", help: "A number literal has no suffix and no leading zero, and `_` stands only between digits. Give the type with an annotation instead, as `let small: u8 = 10`.", span: "The first character at which the literal breaks its grammar: an `_` that isn't between two digits, a leading zero, the character after a base prefix, or the character that directly follows the literal.", retired: false, examples: &[Example { wrong: "fn main() / io {\n  let small = 10u8\n  print(\"{small}\")\n}\n", line: 2, right: "fn main() / io {\n  let small: u8 = 10\n  print(\"{small}\")\n}\n" }] });
/// unterminated string literal
pub const E0005: Code = Code(&Entry { code: "E0005", title: "unterminated string literal", reference: "lexical.string-literals", rule: "A string literal is written `\"…\"`. Every string literal interpolates: an unescaped `{` starts an interpolation (lexical.interpolation). A lone `}` is an ordinary character. Neither a string literal nor an interpolation inside it can hold a raw newline, so an interpolation closes on the line where its string opens. A string literal that its line leaves open is E0005, unterminated string literal, at its opening quote.", tier: "core", phase: "syntax", help: "A string closes on the line where it opens. For text over several lines, write `\\n` inside it.", span: "The string literal's opening quote.", retired: false, examples: &[Example { wrong: "fn greeting(name: str) -> str {\n  \"Hello, {name}\n}\n", line: 2, right: "fn greeting(name: str) -> str {\n  \"Hello, {name}\"\n}\n" }] });
