pub const E0006: Code = Code(&Entry { code: "E0006", title: "invalid escape", reference: "lexical.escapes", rule: "The escapes are `\\n`, `\\t`, `\\r`, `\\0`, `\\\\`, `\\\"`, `\\{` and `\\u{X…}`. The 1 to 6 hexadecimal digits of `\\u{X…}` must name a Unicode scalar value. Any other escape is E0006, invalid escape, at its backslash. So `\\}`, `\\'`, `\\x41`, `\\u0041`, `\\u{}`, `\\u{D800}` and `\\u{110000}` are invalid. `{{` is an invalid escape too, at its first brace, and its fix is `\\{`.", tier: "core", phase: "syntax", help: "Inside a string, `{` starts an interpolation, so a brace is written `\\{`. The other escapes are `\\n`, `\\t`, `\\r`, `\\0`, `\\\\`, `\\\"` and `\\u{…}`.", span: "The backslash that starts the escape, or the first brace of `{{`.", retired: false, examples: &[Example { wrong: "fn braced(x: i64) -> str {\n  \"{{x}}\"\n}\n", line: 2, right: "fn braced(x: i64) -> str {\n  \"\\{{x}}\"\n}\n" }] });
/// malformed format spec
pub const E0007: Code = Code(&Entry { code: "E0007", title: "malformed format spec", reference: "lexical.format-specs", rule: "A format spec has the form `[[fill]align][width][.precision][kind]`. Each of its parts may be left out, so `{42:}` has an empty spec. The parts take these values:\n| Part | Values |\n| --- | --- |\n| `align` | `<`, `^` or `>` |\n| `fill` | Any one character other than `{` and `}` |\n| `width` | A decimal number from 0 to 65535, with no leading zero |\n| `precision` | A decimal number from 0 to 65535, with no leading zero |\n| `kind` | `x`, `X`, `o`, `b` or `e` |\n`{x:05}` is malformed, and isn't a width of 5. Zero padding is written with a fill, as in `{x:0>5}`. A spec that breaks this grammar is E0007, malformed format spec, at the `:` that starts it. So `{x:.2f}`, `{n:+5}`, `{n:#x}` and `{n:65536}` are malformed. std.invalid-specs gives the specs that each type accepts.", tier: "core", phase: "syntax", help: "A format spec gives an alignment, a width, a precision and a kind, each optional, as in `{x:>8.2}` or `{n:x}`. A float's precision is `.2`, with no `f`.", span: "The `:` that starts the spec.", retired: false, examples: &[Example { wrong: "fn price(x: f64) -> str {\n  \"{x:.2f}\"\n}\n", line: 2, right: "fn price(x: f64) -> str {\n  \"{x:.2}\"\n}\n" }] });
/// nesting too deep
pub const E0008: Code = Code(&Entry { code: "E0008", title: "nesting too deep", reference: "lexical.nesting", rule: "Brackets and interpolations nest at most 256 deep. Reading a file's tokens in order, each `(`, `[` and `{`, and the `{` that begins each interpolation (lexical.interpolation), opens one level, and each `)`, `]` and `}`, and the `}` that ends each interpolation, closes the innermost level open, if one is. A file in which a level opens with 256 already open is E0008, nesting too deep, at the bracket that opens it or, for an interpolation, at the `\"` that begins its string literal. The levels are counted over the tokens before the file's first lexical error. Such a file is not parsed, so this error is its only diagnostic, and it declares nothing, as a file that breaks lexical.source-text does. Code that needs deeper nesting names its parts with `let` bindings, functions or types.", tier: "core", phase: "syntax", help: "Brackets and interpolations nest at most 256 deep. Name the inner parts with `let` bindings, functions or types; generated code can do the same.", span: "The bracket that opens the 257th level, or the `\"` that begins the string literal whose interpolation opens it.", retired: false, examples: &[Example { wrong: "fn main() / io {\n  print(\"{((((((((((((((((((((((((((((((((((((((((((((((((((((((((((((((((((((((((((((((((((((((((((((((((((((((((((((((((((((((((((((((((((((((((((((((((((((((((((((((((((((((((((((((((((((((((((((((((((((((((((((((((((((((((((((((((((((((((((((((((((((((((((((((1))))))))))))))))))))))))))))))))))))))))))))))))))))))))))))))))))))))))))))))))))))))))))))))))))))))))))))))))))))))))))))))))))))))))))))))))))))))))))))))))))))))))))))))))))))))))))))))))))))))))))))))))))))))))))))))))))))))))))))))))))))))))))))))}\")\n}\n", line: 2, right: "fn main() / io {\n  let inner = (((1)))\n  print(\"{inner}\")\n}\n" }] });
