/// invalid module name
pub const E0200: Code = Code(&Entry { code: "E0200", title: "invalid module name", reference: "program.module-names", rule: "Below the module root, every `.lt` file is a module. The file `a/b.lt` is module `a.b`, and `main.lt` at the module root is module `main`.\nA program's modules are found through symbolic links to files and directories, each at the link's path. A link to a directory that is, or holds, one of the directories it is found through would make a cycle, and is skipped. Only regular files, and links to them, are modules. Any other entry whose name ends in `.lt`, such as a named pipe or a link that names nothing, is skipped. Entries whose names start with `.`, files and directories alike, are not part of the program: `stilt fmt` skips them, and a macro is given none of them (macros.named-files).\nEach segment of the file's path below the module root, without the `.lt`, must be a lowercase identifier (lexical.identifiers) that is neither a reserved word nor a primitive type name. The first segment must be neither `std`, which names the standard library, nor the name of a dependency of the package (packages.imports). So `a.b.lt`, `Util.lt`, `my-module.lt` and `type.lt` are invalid.\nA file whose module name is invalid is E0200, invalid module name, on its first line. Its declarations are still checked, but no other module can name it. A `use` declaration or a path that names it has the error type (errors.error-type) and is no further error. So does one that names a prefix of its name that isn't a namespace (program.namespaces).", tier: "core", phase: "items", help: "A module's name is its file's path, so each file and directory is named with a lowercase identifier, as `order_lines.lt`, and not `std` or a dependency's name.", span: "The first line of the file.", retired: false, examples: &[] });
/// module header doesn't match its file
pub const E0201: Code = Code(&Entry { code: "E0201", title: "module header doesn't match its file", reference: "program.module-header", rule: "A file may begin with a header: `module` and a path (the `file` production, syntax.programs). The path must be the file's module name. Otherwise the header is E0201, module header doesn't match its file, at the path. So a single file's header always says `module main`.\nA `without` clause may follow the path: on the same line, on the next line, which continues the header (lexical.continuation-lines), or after a `;`. Indentation inside the header has no meaning. The clause limits facts that the compiler infers about the bodies of the module's functions: `panic`, `overflow`, `alloc`, `div`, `copy`, `locks`, the eight capabilities (facts.capabilities) and `unsafe`. Code beyond a limit is E0204 (facts.without). A module without a `without` clause has no limit.", tier: "core", phase: "items", help: "A module's name comes from its file's path, so its header names the module the file is. Change the header, or rename the file.", span: "The module path in the header.", retired: false, examples: &[Example { wrong: "module orders\n\nfn main() {}\n", line: 1, right: "module main\n\nfn main() {}\n" }] });
/// `without` given twice
pub const E0202: Code = Code(&Entry { code: "E0202", title: "`without` given twice", reference: "program.header-limits", rule: "A header holds at most one `without`, and a `without` names each limit at most once. A second `without` in a header is E0202, `without` given twice, at the second occurrence, and so is a limit named twice in one clause. The second occurrence is otherwise ignored. A word after `without` that isn't a limit is a syntax error (E0100), and the name of a tier is such a word. So is a `without` that stands neither in a header nor after a function's signature, where a function's own clause stands (declarations.limits).", tier: "core", phase: "items", help: "A module's header holds one `without`, which names each limit once, as `without panic, alloc`.", span: "The second `without` of a header, or the limit named again.", retired: false, examples: &[Example { wrong: "module main\nwithout panic, alloc, panic\n\npub fn halve(n: i64) -> i64 { n / 2 }\n", line: 2, right: "module main\nwithout panic, alloc\n\npub fn halve(n: i64) -> i64 { n / 2 }\n" }] });
