/// fact beyond a `without` limit
pub const E0204: Code = Code(&Entry { code: "E0204", title: "fact beyond a `without` limit", reference: "facts.without", rule: "A `without` clause names limits. It stands in a module's header (program.module-header) or after a function's signature (declarations.limits). The limits are `panic`, `overflow`, `alloc`, `div`, `copy`, `locks`, the eight capabilities and `unsafe` (the `limits` production, syntax.programs).\nCode limited by `without L` holds no site of the fact `L`, in any module. This covers its own sites and the sites that it inherits from the functions it names. A module's limit covers the bodies of its functions, and a function's limit covers its own body. Each operation that breaks a limit is E0204, fact beyond a `without` limit. Such an operation is a site itself, or names a function that has the fact. Operations on one line beyond one limit are one E0204, at the first of them, which names the others.\nA function limited by `without L`, through its module or its own clause, counts as one without `L` wherever it is named, directly or through other functions. So its own sites are errors where they are written, and its callers get none. Test bodies, doc examples and properties are exempt from every limit. `unsafe` limits a function's own code alone (c.without-unsafe).", tier: "core", phase: "analyses", help: "A `without` promises that the code, and everything it calls, never does what the limit names. Change the code so that it can't, or remove the limit if the code needs it.", span: "The fact: an operation that panics, allocates, may not end or copies shared data, such as a `while`, a call that recurses or goes through a stored function value, an argument copied for a callee that updates it in place, or a write while a copy lasts; a call, a function named as a value, a comparison, an interpolated value or a store that uses a function or impl that does; or the `unsafe` of a block.", retired: false, examples: &[Example { wrong: "module main\nwithout panic\n\npub fn first(prices: List<i64>) -> i64 { prices[0] }\n", line: 4, right: "module main\nwithout panic\n\npub fn first(prices: List<i64>) -> i64 { prices.get(0) else 0 }\n" }, Example { wrong: "fn ratio(part: i64, whole: i64) -> i64 { part * 100 / whole }\n\npub fn share(part: i64, whole: i64) -> i64 without panic { ratio(part, whole) }\n", line: 3, right: "fn ratio(part: i64, whole: i64) -> i64 {\n  if whole == 0 { 0 } else { part * 100 / whole }\n}\n\npub fn share(part: i64, whole: i64) -> i64 without panic { ratio(part, whole) }\n" }] });
/// unknown module
pub const E0205: Code = Code(&Entry { code: "E0205", title: "unknown module", reference: "program.namespaces", rule: "A namespace is a module name or a prefix of one: `std` is a namespace because `std.io` is a module. A `use` may name any namespace. Its path is a lowercase name followed by names of either case (the `use_path` production, syntax.paths), so naming an item is no syntax error. A `use` whose path names neither a namespace nor an item is E0205, unknown module, at the `use`, as `use std.Io`, `use std.io.nothing` and `use nothing` are. The name that the `use` of an E0205 or an E0230 binds has the error type, so the code that names it gets no error of its own.", tier: "core", phase: "items", help: "`use` names a module, as `use std.fs`. A dependency's modules are named after it, once stilt.toml lists it under `[dependencies]`.", span: "The `use` declaration.", retired: false, examples: &[Example { wrong: "use std.fss\n\nfn main() {}\n", line: 1, right: "use std.fs\n\nfn main() {}\n" }] });
/// import cycle
pub const E0206: Code = Code(&Entry { code: "E0206", title: "import cycle", reference: "program.no-cycles", rule: "A module depends on each module that it imports with `use` or `meta use` (macros.meta-use). It also depends on each other module whose item it names in a path, as `fs.read` names an item of `std.fs`. These dependencies must be acyclic. So a module that imports itself is an error, while one that names its own item through its parent, as `a.b.f()` does inside `a.b`, is not.\nEach group of modules that depend on one another in a cycle is one E0206, import cycle. It is reported at the last of the `use` declarations and paths through which they name one another (errors.several-places), and its message shows a whole cycle.", tier: "core", phase: "items", help: "Modules can't import one another in a cycle. Move what both need into a third module, which each imports.", span: "The last of the `use` declarations and paths through which the modules of the cycle depend on one another (errors.several-places). A path is placed at its first name.", retired: false, examples: &[] });
/// local named after an imported module
pub const E0207: Code = Code(&Entry { code: "E0207", title: "local named after an imported module", reference: "program.one-value-namespace", rule: "The names that `use` declarations bind share the value namespace with the functions, constants, variants and macros of the module (declarations.namespaces). So a local binding named after an imported module is E0207, local named after an imported module, at the binding's name. Every use of that binding has the error type. A `use` that binds the name of an item of its module is a name defined twice (E0208). A module is no value, so `let m = fs` after `use std.fs` is a wrong kind of name (E0212).", tier: "core", phase: "types", help: "A local can't take the name of an imported module, since `fs.exists` would then mean two things. Rename the local.", span: "The binding's name.", retired: false, examples: &[Example { wrong: "use std.fs\n\nfn main() / io {\n  let fs = \"notes.txt\"\n  print(fs)\n}\n", line: 4, right: "use std.fs\n\nfn main() / io {\n  let path = \"notes.txt\"\n  print(path)\n}\n" }] });
/// name defined twice
pub const E0208: Code = Code(&Entry { code: "E0208", title: "name defined twice", reference: "declarations.unique-names", rule: "Each place that declares names holds a name once. These are the places:\n- a namespace of a module\n- a list of generics\n- the parameters of a function\n- the fields of a record\n- the operations of an effect\n- the inherent members of a type (traits.inherent-names)\n- the tests of a module (program.test-declarations)\n- the names that one pattern binds\nA second declaration of a name there is E0208, name defined twice, at the later one. `type Order = { qty: i64, qty: i64 }`, `fn g(x: i64, x: i64)` and `let (a, a) = pair` are each E0208.", tier: "core", phase: "types", help: "A name is defined once in its scope, and Stilt has no overloading. Give the second definition a name of its own.", span: "The later of the two names. For a `use` declaration, the declaration, and for a test, its `test` keyword.", retired: false, examples: &[Example { wrong: "fn total(prices: List<i64>) -> i64 { prices.fold(0, |sum, p| sum + p) }\n\nfn total(prices: List<f64>) -> f64 { prices.fold(0.0, |sum, p| sum + p) }\n", line: 3, right: "fn total(prices: List<i64>) -> i64 { prices.fold(0, |sum, p| sum + p) }\n\nfn total_f64(prices: List<f64>) -> f64 { prices.fold(0.0, |sum, p| sum + p) }\n" }] });
/// name of a prelude item
pub const E0209: Code = Code(&Entry { code: "E0209", title: "name of a prelude item", reference: "program.prelude-names", rule: "A module other than `std.prelude` can't declare an item, or bind a name with `use`, that has the name of a prelude item in the same namespace. It can't declare a type or a trait named after a prelude type or trait. It can't declare a variant, a function, a constant or an imported module named after a prelude variant or function.\nDoing so is E0209, name of a prelude item, at the declared name or the `use`. In that module, every use of the name in that namespace has the error type, so it refers to neither item. Other modules still reach the module's item by its qualified name. A primitive type name used as a name is E0210 instead (lexical.primitive-type-names).", tier: "core", phase: "items", help: "The prelude's names, such as `print`, `Option` and `List`, mean the same thing in every module, so nothing else takes them. Choose another name.", span: "The declared name, or the `use` declaration that binds it.", retired: false, examples: &[Example { wrong: "fn print(message: str) {}\n\nfn main() {}\n", line: 1, right: "fn log(message: str) {}\n\nfn main() {}\n" }] });
/// primitive type name used as a name
pub const E0210: Code = Code(&Entry { code: "E0210", title: "primitive type name used as a name", reference: "lexical.primitive-type-names", rule: "The primitive type names are lowercase and reserved: `bool`, `i8`, `i16`, `i32`, `i64`, `u8`, `u16`, `u32`, `u64`, `f32`, `f64` and `str`. They can't name anything else. They are identifiers to the lexer and the grammar. Name resolution rejects any declaration or binding that uses one as its name, which is E0210, primitive type name used as a name. This holds for a type, a field, a function, a method, a parameter, a generic and a binding of a pattern alike.", tier: "core", phase: "types", help: "Type names such as `str`, `i64` and `bool` can't name anything else. Choose another name, such as `text`.", span: "The name.", retired: false, examples: &[Example { wrong: "fn label() -> str {\n  let str = \"a\"\n  str\n}\n", line: 2, right: "fn label() -> str {\n  let text = \"a\"\n  text\n}\n" }] });
