pub const E0212: Code = Code(&Entry { code: "E0212", title: "wrong kind of name", reference: "declarations.wrong-kind-of-name", rule: "A name that resolves to something of a kind that can't stand where it is written is E0212, wrong kind of name, at the name. So each of these is E0212:\n- a record type used as a value, as `Point(1, 2)` or `Point` alone for a record type `Point`\n- a module used as a value\n- a trait used as a type\n- a type named as a bound, as in `<T: Point>`\n- a value parameter or a constant written where a type stands", tier: "core", phase: "types", help: "A name is a value, a type, a trait or a module, and this one is of another kind than the place needs. A record is built with its fields, as `Point { x: 1, y: 2 }`.", span: "The name that refers to the wrong kind of thing.", retired: false, examples: &[Example { wrong: "type Point = { x: i64, y: i64 }\n\nfn origin() -> Point { Point(1, 2) }\n", line: 3, right: "type Point = { x: i64, y: i64 }\n\nfn origin() -> Point { Point { x: 1, y: 2 } }\n" }] });
/// private item
pub const E0213: Code = Code(&Entry { code: "E0213", title: "private item", reference: "program.visibility", rule: "Items are private to their module unless marked `pub`. Naming another module's private item, or a private member of an `impl` block, is E0213, private item, at its name. The fields and variants of a type have the type's visibility. A function or a constant of an inherent `impl` block is private unless marked `pub`, and other modules see a `pub` one only if they see its type.\nThe methods of a trait impl are visible wherever both the trait and the type are. They are written without `pub`, which is a syntax error there (E0100). A call of a trait's method needs the method to be visible, and its trait to be in scope as well (traits.traits-in-scope).", tier: "core", phase: "types", help: "Only an item marked `pub` can be named outside its module. Mark it `pub` in its module, or use what that module exports.", span: "The private item's or member's name.", retired: false, examples: &[] });
/// private item in a public signature
pub const E0214: Code = Code(&Entry { code: "E0214", title: "private item in a public signature", reference: "program.private-in-signatures", rule: "A private type or trait can't appear in a signature that other modules see: that of a `pub` item, or of a `pub` member of a `pub` type. One that does is E0214, private item in a public signature, at the path that names it. A function's signature is its generics, parameter types, return type and row. A constant's signature is its type, a type's is the types of its fields and payloads, and a trait's is the signatures of its methods.", tier: "core", phase: "items", help: "Code outside the module couldn't name a type that a `pub` signature mentions. Mark the type `pub` too, or keep the function private.", span: "The path that names the private type or trait.", retired: false, examples: &[Example { wrong: "type Config = { port: i64 }\n\npub fn default_config() -> Config { Config { port: 8080 } }\n", line: 3, right: "pub type Config = { port: i64 }\n\npub fn default_config() -> Config { Config { port: 8080 } }\n" }] });
/// `self` or `Self` where it doesn't exist
pub const E0215: Code = Code(&Entry { code: "E0215", title: "`self` or `Self` where it doesn't exist", reference: "traits.methods", rule: "A function whose first parameter is `self` is a method, called as `x.m(…)`. `self` may carry the mode `inout`, as `inout self`, under which the method modifies the receiver's place (modes.what-can-be-modified). Only the functions of `impl` and trait blocks take `self`, and `self` exists only in methods.\n`Self` is the block's type in an `impl` block, and in a trait it is the type that implements the trait. `Self` exists nowhere else. `self` or `Self` anywhere else is E0215, `self` or `Self` where it doesn't exist.", tier: "core", phase: "types", help: "`self` exists only in a method, which takes it as its first parameter, and `Self` only in impl and trait blocks. Add `self` to the parameters.", span: "The `self` or `Self`.", retired: false, examples: &[Example { wrong: "type Rect = { w: f64, h: f64 }\n\nimpl Rect {\n  fn width() -> f64 { self.w }\n}\n", line: 4, right: "type Rect = { w: f64, h: f64 }\n\nimpl Rect {\n  fn width(self) -> f64 { self.w }\n}\n" }] });
/// `break` or `continue` outside a loop
pub const E0216: Code = Code(&Entry { code: "E0216", title: "`break` or `continue` outside a loop", reference: "expressions.break-and-continue", rule: "`break` and `continue` take no labels and no values, so `break 5` is a syntax error (E0100). Each acts on the innermost loop whose body holds it. One outside the body of every loop, or separated from its loop by a closure (expressions.closure-boundaries), is E0216. The head of a `while` and the iterable of a `for` are outside the loop's body.", tier: "core", phase: "types", help: "`break` and `continue` act on a `for` or `while` loop, and can't cross a closure. To stop at the first match, use a method such as `find` or `any`.", span: "The `break` or `continue`.", retired: false, examples: &[Example { wrong: "fn first_negative(xs: List<i64>) -> Option<i64> {\n  xs.find(|x| {\n    if x < 0 { break }\n    false\n  })\n}\n", line: 3, right: "fn first_negative(xs: List<i64>) -> Option<i64> {\n  xs.find(|x| x < 0)\n}\n" }] });
/// alternatives bind different names
pub const E0217: Code = Code(&Entry { code: "E0217", title: "alternatives bind different names", reference: "patterns.or-patterns", rule: "In `p₁ | p₂`, every alternative must bind the same names as the first, with the same types. An alternative that binds other names than the first is E0217, alternatives bind different names, at that alternative. An alternative that binds a name with another type is E0311, mismatched types. A name that only some alternatives bind has the error type wherever it is used or bound again, so it causes no further diagnostic (errors.error-type).", tier: "core", phase: "types", help: "Each alternative of a `|` pattern binds the same names, so the arm's body can use them whichever one matched. Give the bindings one name.", span: "The alternative.", retired: false, examples: &[Example { wrong: "type Shape = | Circle(radius: f64) | Square(side: f64)\n\nfn size(s: Shape) -> f64 {\n  match s {\n    Circle(r) | Square(side) => r\n  }\n}\n", line: 5, right: "type Shape = | Circle(radius: f64) | Square(side: f64)\n\nfn size(s: Shape) -> f64 {\n  match s {\n    Circle(r) | Square(r) => r\n  }\n}\n" }] });
/// package that isn't a dependency
pub const E0218: Code = Code(&Entry { code: "E0218", title: "package that isn't a dependency", reference: "packages.imports", rule: "A module's `use` declarations and paths may name modules of its own package, of `std`, and of the packages that its package's manifest names as dependencies. Naming a module of another package of the program, such as a dependency of a dependency, is E0218, package that isn't a dependency, at the `use` or the path. Its fix adds the entry, with the `from` and `version` of the manifest that names that package. A `use` that names a module of no package is E0205 (program.namespaces), whose message lists the manifest's dependencies.\nA module of a package whose name has a dependency's name as its first segment is invalid (E0200, program.module-names). So `src/json.lt`, in a package that depends on `json`, can't be named.", tier: "core", phase: "items", help: "A module imports only from its own package, the standard library and the packages that stilt.toml lists. Add the package to `[dependencies]`.", span: "The `use` declaration.", retired: false, examples: &[] });
/// exported name used twice
pub const E0219: Code = Code(&Entry { code: "E0219", title: "exported name used twice", reference: "c.exported-names", rule: "An exported function's name is its C symbol, as written, so it must be one that no other code of the C program can mean. Two exported functions of a package with one name, in any modules, are E0219, exported name used twice. It is reported at the second's name, in the order of c.library-header. These names are E0352 at the name:\n- a name that c-names.txt lists;\n- a keyword of C11, C23 or C++23;\n- `main`;\n- a name that POSIX.1-2024's headers declare, C17's library among them;\n- a name beginning with `_`, `stilt_`, `lt_`, `f_` or `m_`.", tier: "core", phase: "items", help: "An exported function's name is its C symbol, and C has one namespace, so no two exported functions of a package share a name. Rename one of them.", span: "The name of the second function, in the order of the modules' paths and of the functions in each.", retired: false, examples: &[] });
/// malformed macro pattern
pub const E0220: Code = Code(&Entry { code: "E0220", title: "malformed macro pattern", reference: "macros.pattern-checks", rule: "A pattern must keep these rules:\n- A fragment's name is given once in its pattern, and its kind is one of the six.\n- An `expr`, `pattern` or `type` fragment is followed in its pattern by the end of its group, a `,`, a `;` or `=>`.\n- A repetition holds at least one fragment.\n- A trailing block's kind is `block`.\nNext to a repetition, what follows a matcher is this:\n- A matcher before a repetition is followed by the repetition's first matcher and, when its operator is `*`, by what follows the repetition.\n- A repetition's last matcher is followed by its separator, or by its first matcher when it has none, and by what follows the repetition.\nSo `$($e: expr)*` breaks the rule for an `expr` fragment. A pattern that breaks one of these rules is E0220, malformed macro pattern, at the fragment or at the repetition's `$`.", tier: "advanced", phase: "items", help: "A pattern names each fragment once, with a kind such as `expr` or `name`. An `expr`, `pattern` or `type` fragment is followed by `,`, `;`, `=>` or the end of its group, which tells it where to stop.", span: "The fragment, or the repetition's `$`.", retired: false, examples: &[Example { wrong: "syntax total {\n  ($first: expr $($rest: expr),*) => $first $(+ $rest)*\n}\n\nfn main() / io {\n  print(\"{total!(1, 2, 3)}\")\n}\n", line: 2, right: "syntax total {\n  ($first: expr, $($rest: expr),*) => $first $(+ $rest)*\n}\n\nfn main() / io {\n  print(\"{total!(1, 2, 3)}\")\n}\n" }] });
/// malformed macro template
pub const E0221: Code = Code(&Entry { code: "E0221", title: "malformed macro template", reference: "macros.templates", rule: "An arm's template is the tokens after its `=>`, up to the separator that ends the arm. So a template that spans lines is wrapped in a group, as `{ … }`. In a template, `$name` stands for the fragment that the pattern binds. `$( … ) sep op` repeats its contents once for each round of the pattern's repetition whose fragments it names, with `sep` between the rounds. A template must keep these rules:\n- It names only fragments that its pattern binds, each inside exactly as many repetitions as it was bound in. So a fragment bound outside every repetition can't be named inside one.\n- The fragments that one repetition of the template names come from one repetition of the pattern.\n- Each repetition of the template names a fragment.\nA template that breaks one of these rules is E0221, malformed macro template, at the fragment or at the repetition's `$`. `$` stands nowhere but in a `syntax` declaration and in a quote (macros.splices). Anywhere else it is E0100, syntax error.", tier: "advanced", phase: "items", help: "A template uses only the fragments that its arm's pattern binds, inside as many repetitions, and it parses as an expression or a pattern. Check the fragment's spelling.", span: "The fragment, the repetition's `$`, or the template's first token when it parses as neither.", retired: false, examples: &[Example { wrong: "syntax double {\n  ($number: expr) => $numbr * 2\n}\n\nfn main() / io {\n  print(\"{double!(3)}\")\n}\n", line: 2, right: "syntax double {\n  ($number: expr) => $number * 2\n}\n\nfn main() / io {\n  print(\"{double!(3)}\")\n}\n" }] });
/// use that no arm matches
pub const E0222: Code = Code(&Entry { code: "E0222", title: "use that no arm matches", reference: "macros.matching", rule: "A use's tokens are matched against the arms in order, and the first arm that matches them all is used. Matching doesn't go back into an arm once one of its fragments has matched. Within an arm:\n- a fragment matches the longest form of its kind that its follower allows;\n- a repetition runs as many rounds as it can, stopping before a separator that no further round follows;\n- a trailing block matches the use's trailing block, so an arm without one matches only a use without one.\nA use that no arm matches is E0222, use that no arm matches, at the furthest token that any arm reached. Its message says what that arm expected there, as a closing bracket that came too soon, or no trailing block. A macro whose declaration has an error expands no use, and reports nothing at its uses.", tier: "advanced", phase: "types", help: "A use matches one of the macro's arms token for token. Compare it with the arm that the message names.", span: "The furthest token any arm reached.", retired: false, examples: &[Example { wrong: "syntax between {\n  ($x: expr, $low: expr, $high: expr) => $low <= $x && $x <= $high\n}\n\nfn main() / io {\n  let n = 5\n  print(\"{between!(n, 1)}\")\n}\n", line: 7, right: "syntax between {\n  ($x: expr, $low: expr, $high: expr) => $low <= $x && $x <= $high\n}\n\nfn main() / io {\n  let n = 5\n  print(\"{between!(n, 1, 10)}\")\n}\n" }] });
/// macro out of place
pub const E0223: Code = Code(&Entry { code: "E0223", title: "macro out of place", reference: "macros.uses", rule: "A use of a macro is a path, `!`, and a group, `( … )` or `[ … ]`, of balanced tokens (the `macro_use` production, syntax.macro-uses). The group may be followed on the same line by a `{ … }` group, the use's trailing block. A use in a head doesn't take a trailing block (expressions.heads). A use stands where an expression or a pattern may. Its macro must be one whose templates are all of that form, or the use is E0223, macro out of place, at its path.\nThe grammar reads the groups as tokens. The path is resolved as a function's name is, so `unless!` names the macro `unless` and nothing else, and a local of that name doesn't hide it. A path that names no macro is E0211, unknown name. A path that names something else, and a macro's name written without `!`, are E0212, wrong kind of name (declarations.wrong-kind-of-name). An arm written `( … )` matches only a use written `m!( … )`, and one written `[ … ]` only `m![ … ]`.", tier: "advanced", phase: "types", help: "A macro whose arms give expressions stands where an expression does, and one whose arms give patterns where a pattern does, as in `let pair!(a, b) = p`.", span: "The use's path.", retired: false, examples: &[Example { wrong: "syntax pair {\n  ($a: pattern, $b: pattern) => ($a, $b)\n}\n\nfn main() / io {\n  let p = pair!(1, 2)\n  print(\"{p}\")\n}\n", line: 6, right: "syntax pair {\n  ($a: pattern, $b: pattern) => ($a, $b)\n}\n\nfn main() / io {\n  let pair!(a, b) = (1, 2)\n  print(\"{a} {b}\")\n}\n" }] });
/// expansion too deep
pub const E0224: Code = Code(&Entry { code: "E0224", title: "expansion too deep", reference: "macros.nested-expansions", rule: "A template or a quote may use macros, its own macro among them, and each use in an expansion is expanded in turn. A use expanded inside 128 nested expansions, of pattern and procedural macros together, is E0224, expansion too deep, at the use that the user wrote. Its message names the chain of macros.", tier: "advanced", phase: "types", help: "A macro may use itself, but each expansion must get closer to an arm that stops, and expansions nest at most 128 deep.", span: "The use the user wrote.", retired: false, examples: &[Example { wrong: "syntax sum {\n  ($x: expr) => $x + sum!($x)\n}\n\nfn main() / io {\n  print(\"{sum!(1)}\")\n}\n", line: 6, right: "syntax sum {\n  ($x: expr) => $x\n  ($x: expr, $($rest: expr),+) => $x + sum!($($rest),+)\n}\n\nfn main() / io {\n  print(\"{sum!(1, 2, 3)}\")\n}\n" }] });
/// error raised by a macro
pub const E0225: Code = Code(&Entry { code: "E0225", title: "error raised by a macro", reference: "macros.raised-errors", rule: "A macro that raises `e` gives one diagnostic, E0225, error raised by a macro, at `e`'s span. It carries `e`'s message and notes, and a note that names the macro. A span in a named file places the diagnostic at the literal that names the file, with a note that gives the file's line and column.", tier: "meta", phase: "types", help: "The macro rejected its input, and its message says why. Change the use to give it what it expects.", span: "The raised error's span, or the string literal that names the file it lies in.", retired: false, examples: &[] });
/// macro that didn't finish
pub const E0226: Code = Code(&Entry { code: "E0226", title: "macro that didn't finish", reference: "macros.step-limits", rule: "A macro's run is counted in steps:\n- one for the macro's own body, and one for each call of a function, a method or a closure whose body is written in Stilt, the standard library's included;\n- one for each call of a native;\n- one for each iteration of a loop.\nA run stops when it does one of these:\n- takes more than 10,000,000 steps;\n- calls deeper than 10,000 frames, the macro's own body the first of them;\n- runs out of memory;\n- panics;\n- reaches C, through a foreign function, `with_ptr`, `with_mut_ptr`, `with_c_str` or a native of `std.c` (c.calls).\nA run that stops is E0226, macro that didn't finish, at the use. Its message names the reason, as a panic's kind and detail or the function through which the run reached C. It also names the frames of the macro's module's own functions that were running, innermost last. The use stands as a failed use (macros.failed-uses).", tier: "meta", phase: "types", help: "The macro's code ran too long, ran out of memory or panicked, so it was stopped. Look in the macro for a loop that doesn't end on this input.", span: "The use's path.", retired: false, examples: &[] });
/// use whose parts don't fit its macro
pub const E0227: Code = Code(&Entry { code: "E0227", title: "use whose parts don't fit its macro", reference: "macros.parts", rule: "A use's group is split into parts at its commas outside nested groups. An empty group has no parts, and one trailing comma is ignored. An empty part, as in `m!(a,,b)`, is E0227, use whose parts don't fit its macro, at its second comma. With a trailing block, the last parameter takes the block's contents, without its braces, and the group's parts go to the other parameters in order. Without one, the parts go to the parameters in order. A `meta.Tokens` last parameter then takes every part from its own on, with the commas between them, which may be no part at all. A part too many is E0227 at the part, and a part too few is E0227 at the group's closing bracket.", tier: "meta", phase: "types", help: "A use gives one part per parameter of the macro, separated by commas, and each part has the form its parameter's type asks for: an expression, a pattern, a type or a plain string.", span: "The first token of the part that doesn't fit, the second comma of an empty part, the extra part, or the group's closing bracket when a part is missing.", retired: false, examples: &[] });
/// malformed macro declaration
pub const E0228: Code = Code(&Entry { code: "E0228", title: "malformed macro declaration", reference: "macros.procedural-declarations", rule: "`macro name(p: T, …) -> R / row { body }` declares a procedural macro (the `macro` production, syntax.macros). A procedural macro is an item with a `lower` name in the value namespace of functions, constants and pattern macros. It may be `pub` and take doc comments. Its declaration must keep these rules:\n- Each parameter's type is one of `std.meta`'s input types: `meta.Expr`, `meta.Pattern`, `meta.Type`, `meta.Text`, `meta.File` or `meta.Tokens`. Only the last parameter may be `meta.Tokens`.\n- `R` is `meta.Expr`, `meta.Pattern` or `meta.Type`.\n- The row is empty or `raise<meta.Error>`.\n- The macro has no generics and no `without` clause.\nAnything else is E0228, malformed macro declaration, at the part that breaks the rule. Procedural macros belong to the meta tier (macros.meta-tier).", tier: "meta", phase: "items", help: "A procedural macro works on code, not values: it takes `meta.Expr`, `meta.Pattern`, `meta.Type`, `meta.Text`, `meta.File` or a last `meta.Tokens`, and gives a `meta.Expr`, `meta.Pattern` or `meta.Type`.", span: "The part of the declaration that breaks the rule.", retired: false, examples: &[Example { wrong: "use std.meta\n\n/// The number, doubled.\npub macro double(n: i64) -> meta.Expr { quote { $n * 2 } }\n", line: 4, right: "use std.meta\n\n/// The number, doubled.\npub macro double(n: meta.Expr) -> meta.Expr { quote { $n * 2 } }\n" }] });
/// file that a macro can't be given
pub const E0229: Code = Code(&Entry { code: "E0229", title: "file that a macro can't be given", reference: "macros.named-files", rule: "A `meta.File` part's value is a path relative to a directory. The directory is that of the manifest of the package whose source holds the literal, or that of the program's root file when there is no manifest. The path must keep these rules:\n- its names are separated by `/`, and none of them is empty, `.` or `..`, or starts with `.`;\n- each name matches an entry of its directory byte for byte;\n- it names a regular file whose real path lies inside the directory it is relative to, and whose contents are UTF-8.\nAny other path is E0229, file that a macro can't be given, at the literal. The compiler reads the file, and a macro reads nothing itself. The file is an input of the program: an edit of it expands again the uses that name it.", tier: "meta", phase: "types", help: "A macro reads only a regular UTF-8 file inside the package, named by a relative path spelled exactly as on disk, so that every machine builds the same program.", span: "The string literal that names the file.", retired: false, examples: &[] });
/// `use` of an item
pub const E0230: Code = Code(&Entry { code: "E0230", title: "`use` of an item", reference: "program.what-use-binds", rule: "`use a.b.c` makes module `a.b.c` available under the name `c`. Code names the module's items through that name, by qualified names such as `fs.read(…)` and `orders.Order`. `use` imports modules, never individual items. There are no import aliases and no re-exports.\nA `use` whose path names no namespace (program.namespaces), but names an item of a module as a path in code does, is E0230, `use` of an item, at the `use`. Its path names an item when, after the first name along it that is a module, the next name is an item that the module declares, whatever its visibility. The item is a function, a constant, a type or one of its variants, a trait, an effect or a macro.\nSo `use std.sync.Shared`, `use std.io.read_line` and `use std.sync.Shared.new` are E0230. The message names the item as code names it through its module, as `sync.Shared`, and the fix writes the module's path, `use std.sync`.", tier: "core", phase: "items", help: "`use` imports a module, never an item: write `use std.sync`, then name the item through the module, as `sync.Shared`.", span: "The `use` declaration.", retired: false, examples: &[Example { wrong: "use std.sync.Shared\n\nfn counter() -> Shared<i64> { Shared.new(0) }\n", line: 1, right: "use std.sync\n\nfn counter() -> sync.Shared<i64> { sync.Shared.new(0) }\n" }] });
/// expansion too large
pub const E0231: Code = Code(&Entry { code: "E0231", title: "expansion too large", reference: "macros.expansion-size", rule: "The expansions that a use the user wrote leads to hold at most 100,000 tokens in all. They are the use's own expansion and every expansion nested in it, of pattern and procedural macros together. Each counts the tokens of the code it gives: a pattern macro's template with its fragments substituted, or a procedural macro's result. An expansion that takes the count past 100,000 is E0231, expansion too large, at the use that the user wrote. Its message names the macro that gave it. After an expansion too large, or too deep (macros.nested-expansions), nothing more of that use's expansions is resolved or reported, and the use has no expansion.", tier: "advanced", phase: "types", help: "A use's expansions, its own and those nested in it, hold at most 100,000 tokens in all. A macro that uses another several times at each level multiplies its code at each one: use it once and reuse its result, or build the repeated part in a function.", span: "The use the user wrote.", retired: false, examples: &[Example { wrong: "syntax q0 { () => 1 }\nsyntax q1 { () => q0!() + q0!() + q0!() + q0!() }\nsyntax q2 { () => q1!() + q1!() + q1!() + q1!() }\nsyntax q3 { () => q2!() + q2!() + q2!() + q2!() }\nsyntax q4 { () => q3!() + q3!() + q3!() + q3!() }\nsyntax q5 { () => q4!() + q4!() + q4!() + q4!() }\nsyntax q6 { () => q5!() + q5!() + q5!() + q5!() }\nsyntax q7 { () => q6!() + q6!() + q6!() + q6!() }\nsyntax q8 { () => q7!() + q7!() + q7!() + q7!() }\n\nfn main() / io {\n  print(\"{q8!()}\")\n}\n", line: 12, right: "syntax q0 { () => 1 }\nsyntax q1 { () => 4 * q0!() }\nsyntax q2 { () => 4 * q1!() }\nsyntax q3 { () => 4 * q2!() }\nsyntax q4 { () => 4 * q3!() }\nsyntax q5 { () => 4 * q4!() }\nsyntax q6 { () => 4 * q5!() }\nsyntax q7 { () => 4 * q6!() }\nsyntax q8 { () => 4 * q7!() }\n\nfn main() / io {\n  print(\"{q8!()}\")\n}\n" }] });
/// wrong number of type arguments
pub const E0300: Code = Code(&Entry { code: "E0300", title: "wrong number of type arguments", reference: "declarations.type-arguments", rule: "Wherever a type is written, a generic type takes exactly as many type arguments as it has parameters, as in `List<i64>`. This holds for a record, a variant type and a built-in type such as `List`. Any other number is E0300, wrong number of type arguments: `List`, `Option<i64, str>` and `T<i64>` for a type parameter `T` are each E0300. A type parameter and `Self` take none, except in a constructor trait (traits.constructor-traits) and for a constructor parameter (traits.constructor-parameters). A type with value parameters takes a value argument in the position of each (generics.value-arguments).\nExpressions and patterns name a generic type without its arguments, which inference gives (types.no-type-arguments), as in `Map.with_default(0.0)` and `Point { x: 1 }`.", tier: "core", phase: "types", help: "A generic type takes one type argument per parameter, as `Map<str, i64>` for a map from strings to integers.", span: "The type.", retired: false, examples: &[Example { wrong: "fn count(words: Map<str>) -> i64 { words.len() }\n", line: 1, right: "fn count(words: Map<str, i64>) -> i64 { words.len() }\n" }] });
/// inherent impl outside the type's module
pub const E0301: Code = Code(&Entry { code: "E0301", title: "inherent impl outside the type's module", reference: "traits.impl-blocks", rule: "A type's home module may hold blocks of the form `impl<A, …> Type<A, …> { … }`, which hold functions and constants of the type. Such a block is an inherent impl. No other module may hold one: an inherent impl outside the type's module is E0301, inherent impl outside the type's module. So a program adds methods to a built-in type, whose home is `std.prelude`, only through a trait of its own.\nThe block's type must be a type constructor of the module applied to the block's parameters, type and value, each once, in any order. Any other type is E0302, invalid impl type. `impl<T> List<T>` is valid in `std.prelude`, while `impl List<i64>`, `impl<A> Pair<A, A>`, `impl<A, B, C> Pair<A, B>` and `impl (i64, i64)` are not.", tier: "core", phase: "items", help: "A type's own methods live in the type's module. Move the impl block there, or write a function in this module instead.", span: "The impl's type.", retired: false, examples: &[] });
/// invalid impl type
pub const E0302: Code = Code(&Entry { code: "E0302", title: "invalid impl type", reference: "traits.impl-blocks", rule: "A type's home module may hold blocks of the form `impl<A, …> Type<A, …> { … }`, which hold functions and constants of the type. Such a block is an inherent impl. No other module may hold one: an inherent impl outside the type's module is E0301, inherent impl outside the type's module. So a program adds methods to a built-in type, whose home is `std.prelude`, only through a trait of its own.\nThe block's type must be a type constructor of the module applied to the block's parameters, type and value, each once, in any order. Any other type is E0302, invalid impl type. `impl<T> List<T>` is valid in `std.prelude`, while `impl List<i64>`, `impl<A> Pair<A, A>`, `impl<A, B, C> Pair<A, B>` and `impl (i64, i64)` are not.", tier: "core", phase: "items", help: "An impl block applies to the whole generic type, as `impl<A, B> Pair<A, B>`. For one instantiation alone, write a function that takes it.", span: "The impl's type.", retired: false, examples: &[Example { wrong: "type Pair<A, B> = { first: A, second: B }\n\nimpl Pair<i64, i64> {\n  fn sum(self) -> i64 { self.first + self.second }\n}\n", line: 3, right: "type Pair<A, B> = { first: A, second: B }\n\nfn sum(p: Pair<i64, i64>) -> i64 { p.first + p.second }\n" }] });
/// orphan impl
pub const E0303: Code = Code(&Entry { code: "E0303", title: "orphan impl", reference: "traits.orphan-rule", rule: "An impl must be in its trait's module or in its type's module. An impl anywhere else is an orphan impl, which is E0303. So no module can give `f64` an impl of `Hash`, because both are declared in `std.prelude`.", tier: "core", phase: "items", help: "An impl of a trait lives in the trait's module or the type's module, so that a type never gets two impls of one trait from two places. Move it to one of them.", span: "The impl's `impl` keyword.", retired: false, examples: &[] });
/// overlapping impls
pub const E0304: Code = Code(&Entry { code: "E0304", title: "overlapping impls", reference: "traits.coherence", rule: "A trait has at most one impl per type constructor. A second impl is E0304, overlapping impls, at the later impl. An impl covers a whole constructor, so no impl for `List<str>` stands beside one for every `List<T>`.", tier: "core", phase: "items", help: "A type has at most one impl of each trait, so a call always means one thing. Delete one of the impls, or merge them.", span: "The later impl's `impl` keyword.", retired: false, examples: &[Example { wrong: "trait Named {\n  fn name(self) -> str\n}\n\ntype Thing = {}\n\nimpl Named for Thing {\n  fn name(self) -> str { \"a\" }\n}\n\nimpl Named for Thing {\n  fn name(self) -> str { \"b\" }\n}\n", line: 11, right: "trait Named {\n  fn name(self) -> str\n}\n\ntype Thing = {}\n\nimpl Named for Thing {\n  fn name(self) -> str { \"a\" }\n}\n" }] });
/// missing trait member
pub const E0305: Code = Code(&Entry { code: "E0305", title: "missing trait member", reference: "traits.impl-members", rule: "A trait impl holds a member for each function and constant of the trait that has no default. It may leave out those that have one, whose default then applies. A member that it lacks is E0305, missing trait member, at the impl. It holds no other member: one that the trait doesn't declare is E0306, member not in the trait, at its name. Its members take no `pub`, and are visible wherever both the trait and the type are (program.visibility).", tier: "core", phase: "items", help: "A trait impl defines every method and constant of the trait that has no default. Add the missing member.", span: "The impl's `impl` keyword.", retired: false, examples: &[Example { wrong: "trait Shape {\n  fn area(self) -> f64\n  fn name(self) -> str\n}\n\ntype Circle = { radius: f64 }\n\nimpl Shape for Circle {\n  fn area(self) -> f64 { 3.14 * self.radius * self.radius }\n}\n", line: 8, right: "trait Shape {\n  fn area(self) -> f64\n  fn name(self) -> str\n}\n\ntype Circle = { radius: f64 }\n\nimpl Shape for Circle {\n  fn area(self) -> f64 { 3.14 * self.radius * self.radius }\n  fn name(self) -> str { \"circle\" }\n}\n" }] });
/// member not in the trait
pub const E0306: Code = Code(&Entry { code: "E0306", title: "member not in the trait", reference: "traits.impl-members", rule: "A trait impl holds a member for each function and constant of the trait that has no default. It may leave out those that have one, whose default then applies. A member that it lacks is E0305, missing trait member, at the impl. It holds no other member: one that the trait doesn't declare is E0306, member not in the trait, at its name. Its members take no `pub`, and are visible wherever both the trait and the type are (program.visibility).", tier: "core", phase: "items", help: "A trait impl holds only the trait's members. Move the other methods to an inherent `impl` block of the type.", span: "The member's name.", retired: false, examples: &[Example { wrong: "trait Shape {\n  fn area(self) -> f64\n}\n\ntype Circle = { radius: f64 }\n\nimpl Shape for Circle {\n  fn area(self) -> f64 { 3.14 * self.radius * self.radius }\n  fn perimeter(self) -> f64 { 6.28 * self.radius }\n}\n", line: 9, right: "trait Shape {\n  fn area(self) -> f64\n}\n\ntype Circle = { radius: f64 }\n\nimpl Shape for Circle {\n  fn area(self) -> f64 { 3.14 * self.radius * self.radius }\n}\n\nimpl Circle {\n  fn perimeter(self) -> f64 { 6.28 * self.radius }\n}\n" }] });
/// method signature differs from the trait's
pub const E0307: Code = Code(&Entry { code: "E0307", title: "method signature differs from the trait's", reference: "traits.impl-signatures", rule: "Each member of a trait impl has the signature that the trait declares, with `Self` replaced by the impl's type. Each trait parameter is replaced by its argument (traits.trait-arguments). So the member has the same parameter modes and types, the same parameters written `escaping`, and the same return type and row as the trait's declaration. Its result is written `inout` where the trait's is (projections.declaring-projection).\nThe member's generics correspond to those of the trait function in order, with the same bounds, and may have other names. A member whose signature differs is E0307, method signature differs from the trait's, at its name. A trait method's non-escaping parameters pass their arguments' effects through, as a function's do (effects.non-escaping-parameters). So the method of every impl passes them through alike, and so does a call through a bound.", tier: "core", phase: "items", help: "Callers rely on the signature that the trait declares, so the impl's method takes the same parameters and returns the same result, with `Self` as the impl's type.", span: "The method's name.", retired: false, examples: &[Example { wrong: "trait Shape {\n  fn area(self) -> f64\n}\n\ntype Square = { side: i64 }\n\nimpl Shape for Square {\n  fn area(self) -> i64 { self.side * self.side }\n}\n", line: 8, right: "trait Shape {\n  fn area(self) -> f64\n}\n\ntype Square = { side: f64 }\n\nimpl Shape for Square {\n  fn area(self) -> f64 { self.side * self.side }\n}\n" }] });
/// inherent method hides a trait method
pub const E0308: Code = Code(&Entry { code: "E0308", title: "inherent method hides a trait method", reference: "traits.name-clashes", rule: "A type can't have an inherent function with the name of a function or a constant of a trait it implements. This holds whether the type implements the trait through an impl that the program writes or through a structural impl (traits.structural-impls). The two are E0308, inherent method hides a trait method. Here a generic type counts as implementing a structural trait when it would implement it with every type parameter implementing it. So a record with an inherent `show` is E0308, unless the type of one of its fields can't be shown, as a function type can't.", tier: "core", phase: "items", help: "A method's name means one member of a type, so an inherent method and a trait's method can't share it. Rename the inherent method.", span: "The trait impl's `impl` keyword, or the inherent method's name when the impl is structural.", retired: false, examples: &[Example { wrong: "type Point = { x: i64, y: i64 }\n\nimpl Point {\n  fn show(self) -> str { \"({self.x}, {self.y})\" }\n}\n\nimpl Show for Point {\n  fn show(self) -> str { \"Point({self.x}, {self.y})\" }\n}\n", line: 7, right: "type Point = { x: i64, y: i64 }\n\nimpl Point {\n  fn pair(self) -> str { \"({self.x}, {self.y})\" }\n}\n\nimpl Show for Point {\n  fn show(self) -> str { \"Point({self.x}, {self.y})\" }\n}\n" }] });
/// record that contains itself
pub const E0309: Code = Code(&Entry { code: "E0309", title: "record that contains itself", reference: "declarations.recursive-types", rule: "A type may contain itself, directly or through other types, and needs no box. A record must not contain itself through record fields and tuple elements alone, with no variant type, collection or function type in between. Declaring one is E0309, record that contains itself. Each group of records that contain one another this way is one error, at the last of their declarations. So `type Link = { value: i64, next: Link }` is E0309, while `next: Option<Link>` or `next: List<Link>` is valid.", tier: "core", phase: "items", help: "Building such a record would need one already built, forever. Make the field optional, as `next: Option<Node>`, or a list.", span: "The name of the last record of the group that contains itself (errors.several-places).", retired: false, examples: &[Example { wrong: "type Node = { value: i64, next: Node }\n", line: 1, right: "type Node = { value: i64, next: Option<Node> }\n" }] });
/// invalid `main`
pub const E0310: Code = Code(&Entry { code: "E0310", title: "invalid `main`", reference: "program.main", rule: "A program's entry point is the function `main` of module `main`. It has no parameters and returns `()`. Its row holds at most these effects:\n- `io`;\n- a `raise<E>` whose `E` implements `Show`;\n- `async`, under which its tasks run in sequence (tasks.sequential-run).\nA user-defined effect in its row is E0512 (handlers.no-effect-reaches-main). Any other signature is E0310, invalid `main`, at its name, a generic one, one with a row variable and one that returns `Never` among them. The command-line arguments come from `std.cli` (std.cli). A function `main` of any other module is an ordinary function.", tier: "core", phase: "items", help: "`main` takes no parameters and returns nothing, and its row allows only `io` and raising an error that can be shown. Read the command line with `std.cli`'s `args()`.", span: "The name of `main`.", retired: false, examples: &[Example { wrong: "fn main(args: List<str>) / io {\n  print(\"{args.len()}\")\n}\n", line: 1, right: "use std.cli\n\nfn main() / io {\n  print(\"{cli.args().len()}\")\n}\n" }] });
/// mismatched types
pub const E0311: Code = Code(&Entry { code: "E0311", title: "mismatched types", reference: "types.mismatch", rule: "A type mismatch is an expression whose type differs from its expected type. It is E0311, mismatched types, at that expression.", tier: "core", phase: "types", help: "Stilt never converts a value to another type on its own. Give a value of the expected type, convert it with a method such as `to_f64()`, or change what expects it.", span: "The expression or pattern whose type differs. A block without a final expression is reported at the function's name, the `test` keyword, or the `if` or block whose value it gives.", retired: false, examples: &[Example { wrong: "fn discounted(price: i64) -> i64 { price * 0.9 }\n", line: 1, right: "fn discounted(price: i64) -> i64 { price * 9 / 10 }\n" }, Example { wrong: "fn main() / io {\n  let n: i64 = \"3\"\n  print(\"{n}\")\n}\n", line: 2, right: "fn main() / io {\n  let n: i64 = 3\n  print(\"{n}\")\n}\n" }] });
/// type that can't be inferred
pub const E0312: Code = Code(&Entry { code: "E0312", title: "type that can't be inferred", reference: "types.known-types", rule: "These four positions must have types known where they are used, from what precedes them in evaluation order:\n- the receiver of a method call (traits.method-resolution);\n- the base of a field access;\n- an indexed value;\n- the iterable of a `for`.\nA type is known when its outermost constructor is. So after `var xs = []`, the call `xs.push(1)` is valid and decides the element type. A literal whose type is still open at one of these positions takes its default type (numbers.literal-defaults). Any other unknown type there is E0312, type that can't be inferred, which asks for an annotation.", tier: "core", phase: "types", help: "A type is inferred from how its value is used within its body, and nothing here says which it is. Write it, as `let orders: List<i64> = []`.", span: "The expression whose type isn't known. For a type the body leaves undecided, the expression that introduced it.", retired: false, examples: &[Example { wrong: "fn main() / io {\n  let orders = []\n  print(\"{orders.len()} orders\")\n}\n", line: 2, right: "fn main() / io {\n  let orders: List<i64> = []\n  print(\"{orders.len()} orders\")\n}\n" }] });
/// no such field
pub const E0313: Code = Code(&Entry { code: "E0313", title: "no such field", reference: "types.field-access", rule: "`e.f` requires `e` to have a record type with a field `f`. `e.n` requires `e` to have a tuple type with more than `n` elements. Any other field is E0313, no such field. A field access whose operand has type `Option` reads through it instead (types.fields-through-option). Calling a field or a tuple element that holds a function is a method call (traits.method-resolution).", tier: "core", phase: "types", help: "Check the field's name against the type's declaration. A `Shared<T>`'s fields are read inside `when`, and a field read through an `Option` is the field of the value inside it.", span: "The field's name.", retired: false, examples: &[Example { wrong: "type Order = { id: i64, total: i64 }\n\nfn amount(o: Order) -> i64 { o.totl }\n", line: 3, right: "type Order = { id: i64, total: i64 }\n\nfn amount(o: Order) -> i64 { o.total }\n" }] });
/// no such method or member
pub const E0314: Code = Code(&Entry { code: "E0314", title: "no such method or member", reference: "traits.method-resolution", rule: "In a method call `recv.m(args)`, the receiver's type must be known where the call stands (types.known-types). Otherwise the call is E0312, type that can't be inferred, which asks for an annotation. With `C` the head constructor of that type, as `List` is for a `List<str>`, `m` is looked up in this order:\n1. An inherent function `m` of `C`. If it takes no `self`, the call is E0314, which shows the form `C.m(…)`. 2. Otherwise, a method `m` of a trait in scope (traits.traits-in-scope) that has an impl for `C`. If the impl has bounds that the receiver's type arguments don't meet, the call is E0318, which names the missing bound. 3. For a receiver whose type is a type parameter, or is headed by a constructor parameter (traits.constructor-parameters), the methods of the traits of its bounds. 4. Otherwise, a field `m` of the record type, or the element `m` of the tuple type, as in `pair.0(x)`. Its type must be a function type, or the call is E0311, mismatched types. The call calls its value. Parentheses only group, so `(r.m)(x)` means `r.m(x)`.\nWhen none of these finds `m`, the call is E0314, no such method or member.", tier: "core", phase: "types", help: "Check the method's name and the receiver's type. A function without `self` is named on its type, as `List.new()`, and a trait's method needs an impl of the trait for the type.", span: "The method's or member's name.", retired: false, examples: &[Example { wrong: "fn count(names: List<str>) -> i64 { names.size() }\n", line: 1, right: "fn count(names: List<str>) -> i64 { names.len() }\n" }] });
/// wrong number of arguments
pub const E0315: Code = Code(&Entry { code: "E0315", title: "wrong number of arguments", reference: "expressions.arguments", rule: "Arguments are positional, and a call must give one argument for each parameter (E0315). There are no named arguments, no default values and no variadic functions. So `area(w: 2.0, h: 2.0)` is a syntax error (E0100).", tier: "core", phase: "types", help: "A call gives one argument per parameter, in order, since Stilt has no default arguments and no overloading.", span: "The call, the closure or the variant pattern.", retired: false, examples: &[Example { wrong: "fn area(width: i64, height: i64) -> i64 { width * height }\n\nfn square(side: i64) -> i64 { area(side) }\n", line: 3, right: "fn area(width: i64, height: i64) -> i64 { width * height }\n\nfn square(side: i64) -> i64 { area(side, side) }\n" }] });
/// field given twice or left out
pub const E0316: Code = Code(&Entry { code: "E0316", title: "field given twice or left out", reference: "expressions.struct-literal-fields", rule: "A struct literal's fields are written `Name { f: e, g }`, where a bare `g` is short for `g: g`. Every field of the record must be given exactly once (E0316), and a field that the record doesn't have is E0313. `Name { ..base, f: e }` gives some fields and copies the others from `base` (records.update).", tier: "core", phase: "types", help: "A record literal gives every field once, and a record pattern names every field, or ends with `..` to leave the others out.", span: "The repeated field's name. For a field left out, the literal's or pattern's type.", retired: false, examples: &[Example { wrong: "type Order = { id: i64, total: i64 }\n\nfn first() -> Order { Order { id: 1 } }\n", line: 3, right: "type Order = { id: i64, total: i64 }\n\nfn first() -> Order { Order { id: 1, total: 0 } }\n" }] });
/// operator not defined on a type
pub const E0317: Code = Code(&Entry { code: "E0317", title: "operator not defined on a type", reference: "expressions.left-operand-first", rule: "A binary operator checks its left operand first. If the left operand's type is known and the operator isn't defined on it (Numbers), the operation is E0317, operator not defined on a type. The right operand is then checked alone, with no expected type. So `\"total: \" + n` is E0317, with the fix of expressions.no-string-plus, whatever the type of `n`. On a type that isn't numeric, `==`, `!=` and the ordering operators are defined through `Eq` and `Ord` (traits.prelude-traits). So on a type without the impl, they are E0318, not E0317, as `<` on a `Map` is.", tier: "core", phase: "types", help: "Arithmetic works on numbers, bitwise operators on integers, and `!`, `&&` and `||` on `bool`. A string is built with interpolation, as `\"Hello, {name}\"`, not with `+`.", span: "The operation. For a compound assignment, the assigned place; for a range, its start.", retired: false, examples: &[Example { wrong: "fn greeting(name: str) -> str { \"Hello, \" + name }\n", line: 1, right: "fn greeting(name: str) -> str { \"Hello, {name}\" }\n" }] });
/// unsatisfied bound
pub const E0318: Code = Code(&Entry { code: "E0318", title: "unsatisfied bound", reference: "traits.unsatisfied-bounds", rule: "Inside a function, a type parameter's bounds are all that is known of its type. The methods of their traits, and the operators that those traits stand behind (traits.operators), apply to its values. Where a type parameter is given a type, as at a call, the type must meet each of its bounds. A method's receiver must meet the bounds of the impl or the block that holds the method (traits.bounded-blocks).\nA use that needs an impl that a type lacks is E0318, unsatisfied bound, at the use, and the diagnostic names the type and the trait. So `a == b` on a type parameter without `Eq` is E0318, and so is `m[k]` on a `Map<K, V>` whose `K` lacks the bound `Eq + Hash`.", tier: "core", phase: "types", help: "Using a trait's operation on a type parameter needs the bound, as `<T: Show>` to interpolate a `T`. A type passed in implements the trait: write its `impl`, or choose a type that has one.", span: "Where the bound is needed: the function's or method's name, the operation, the interpolated expression, or the test or doc example.", retired: false, examples: &[Example { wrong: "fn describe<T>(x: T) -> str { \"{x}\" }\n", line: 1, right: "fn describe<T: Show>(x: T) -> str { \"{x}\" }\n" }] });
/// ambiguous method
pub const E0319: Code = Code(&Entry { code: "E0319", title: "ambiguous method", reference: "traits.ambiguous-methods", rule: "When methods of several traits in scope match a call, the call is E0319, ambiguous method. The fix is the qualified form, which names the trait (traits.qualified-calls).", tier: "core", phase: "types", help: "Two traits give the type a method of that name, so the call names the trait it means, as `Report.describe(o)`.", span: "The method's name.", retired: false, examples: &[Example { wrong: "trait Report {\n  fn describe(self) -> str\n}\n\ntrait Audit {\n  fn describe(self) -> str\n}\n\ntype Order = { id: i64 }\n\nimpl Report for Order {\n  fn describe(self) -> str { \"order {self.id}\" }\n}\n\nimpl Audit for Order {\n  fn describe(self) -> str { \"audited order {self.id}\" }\n}\n\nfn summary(o: Order) -> str { o.describe() }\n", line: 19, right: "trait Report {\n  fn describe(self) -> str\n}\n\ntrait Audit {\n  fn describe(self) -> str\n}\n\ntype Order = { id: i64 }\n\nimpl Report for Order {\n  fn describe(self) -> str { \"order {self.id}\" }\n}\n\nimpl Audit for Order {\n  fn describe(self) -> str { \"audited order {self.id}\" }\n}\n\nfn summary(o: Order) -> str { Report.describe(o) }\n" }] });
/// literal out of range
pub const E0320: Code = Code(&Entry { code: "E0320", title: "literal out of range", reference: "numbers.integer-literals", rule: "An integer literal (lexical.integer-literals) takes the numeric type its context expects, a float type included, so `let x: f64 = 1` is valid. A literal that doesn't fit its type is E0320, literal out of range. An integer literal used as a float fits only if the float type represents it exactly, so `9007199254740993` can't be an `f64`.", tier: "core", phase: "types", help: "The literal doesn't fit its type. Choose a wider type, as `u16` for 300, or a value that fits.", span: "The literal, including a `-` written directly before it.", retired: false, examples: &[Example { wrong: "fn volume() -> u8 { 300 }\n", line: 1, right: "fn volume() -> u16 { 300 }\n" }] });
/// refutable pattern
pub const E0321: Code = Code(&Entry { code: "E0321", title: "refutable pattern", reference: "patterns.irrefutable-positions", rule: "A pattern is irrefutable when its form alone guarantees a match. These patterns are irrefutable:\n- `_`, a binding and `()`\n- a tuple or record pattern whose parts are irrefutable\n- a variant of a type with a single variant, whose payload patterns are irrefutable\n- `[..]` and `[..rest]`\n- an or-pattern with an irrefutable alternative\nA list pattern on an array is irrefutable when its elements are (generics.array-exhaustiveness). Every other pattern is refutable, even one that matches every value, as `A(x) | B(x)` does for a type whose only variants are `A` and `B`.\nThe patterns of `let` and `var` without `else`, of `for` heads and of closure parameters must be irrefutable. A refutable pattern there is E0321, refutable pattern. A closure parameter marked `inout` is a name, not a pattern (expressions.inout-closure-parameters).", tier: "core", phase: "types", help: "This pattern can fail to match, so the code needs a way out: write `let Some(n) = name else return …`, or use `match` or `if let`.", span: "The pattern.", retired: false, examples: &[Example { wrong: "fn first_name(name: Option<str>) -> str {\n  let Some(n) = name\n  n\n}\n", line: 2, right: "fn first_name(name: Option<str>) -> str {\n  let Some(n) = name else return \"nobody\"\n  n\n}\n" }] });
/// unused value
pub const E0322: Code = Code(&Entry { code: "E0322", title: "unused value", reference: "expressions.unused-values", rule: "An expression statement that isn't the last statement of its block must have type `()` or `Never`. Any other type there is E0322, unused value. So `xs.sorted()` on its own line, which returns a new list and changes nothing, is an error. `let _ = e` discards a value on purpose. A loop's body discards its value, so its last expression statement is held to the same rule.", tier: "core", phase: "types", help: "A value that a statement computes and drops is usually a mistake, such as calling a method that returns a new list instead of changing the old one. Use the value, or write `let _ = …` to drop it on purpose.", span: "The expression statement.", retired: false, examples: &[Example { wrong: "fn report(prices: List<i64>) -> str {\n  prices.len()\n  \"{prices}\"\n}\n", line: 2, right: "fn report(prices: List<i64>) -> str {\n  \"{prices.len()} prices: {prices}\"\n}\n" }] });
/// value of an `if` without `else`
pub const E0323: Code = Code(&Entry { code: "E0323", title: "value of an `if` without `else`", reference: "expressions.if", rule: "Without an `else`, the block of `if c { … }` must have type `()` or `Never` (E0323), and the `if` has type `()`. With an `else`, both branches must have a common type, and a branch of type `Never` agrees with any type. Without an expected type, the first branch whose type isn't `Never` sets the common type. The other branch is checked against it (types.expected-types), so a mismatch is reported in that branch. The condition of an `if` may also be a bound test (meta.bound-tests), and an `if` may carry a staging annotation (meta.staging-annotations).", tier: "core", phase: "types", help: "An `if` without `else` gives no value, so it can't end a block that gives one. Add the `else` branch.", span: "The `if`.", retired: false, examples: &[Example { wrong: "fn label(n: i64) -> str {\n  if n > 0 { \"positive\" }\n  \"zero or less\"\n}\n", line: 2, right: "fn label(n: i64) -> str {\n  if n > 0 { \"positive\" } else { \"zero or less\" }\n}\n" }] });
/// key path where no function is expected
pub const E0324: Code = Code(&Entry { code: "E0324", title: "key path where no function is expected", reference: "expressions.key-paths", rule: "A key path is `.` followed by a chain of field accesses, tuple fields, indexing and method calls, as in `.1`, `.paid`, `.items[0]` or `.name.len()`. The chain starts with a field, a tuple field or a method call, and indexing may follow any of them. A key path `K` means `|x| xK`, so `.paid` means `|x| x.paid`. A key path is allowed only where a function type `fn(T) -> U` is expected. Anywhere else it is E0324, key path where no function is expected. The arguments and indexes in the chain are expressions of their own, so `.items.map(.price)` holds a second key path. A key path's fields read through an `Option` as any field does (types.option-key-paths).", tier: "core", phase: "types", help: "A key path such as `.total` is short for `|x| x.total`, and stands only where a function is expected, as in `orders.map(.total)`.", span: "The key path.", retired: false, examples: &[Example { wrong: "type Order = { total: i64 }\n\nfn totals(orders: List<Order>) -> List<i64> {\n  let get = .total\n  orders.map(get)\n}\n", line: 4, right: "type Order = { total: i64 }\n\nfn totals(orders: List<Order>) -> List<i64> {\n  orders.map(.total)\n}\n" }] });
/// invalid format spec
pub const E0325: Code = Code(&Entry { code: "E0325", title: "invalid format spec", reference: "std.invalid-specs", rule: "A spec that doesn't apply to its operand's type is E0325, invalid format spec, at the interpolated expression. A spec doesn't apply in these cases:\n- a precision without a kind, or the kind `e`, on anything but a float;\n- `x`, `X`, `o` or `b` on anything but an integer, or with a precision.\nThe operand's type is the one its whole body gives it, after the defaults of numbers.literal-defaults, so a spec never decides the type of a literal. After `let x = 5`, `\"{x:.2}\"` is E0325 unless the rest of the body makes `x` a float. A spec that breaks the grammar of specs is E0007, malformed format spec (lexical.format-specs).", tier: "core", phase: "types", help: "A precision and `e` apply to floats, and `x`, `X`, `o` and `b` to integers. Convert the value first, or use a spec that fits its type.", span: "The interpolated expression.", retired: false, examples: &[Example { wrong: "fn hex(n: f64) -> str { \"{n:x}\" }\n", line: 1, right: "fn hex(n: i64) -> str { \"{n:x}\" }\n" }] });
/// constant's value isn't a constant expression
pub const E0326: Code = Code(&Entry { code: "E0326", title: "constant's value isn't a constant expression", reference: "declarations.constant-expressions", rule: "A constant's value is a constant expression, built only from these parts:\n- literals, with no interpolation in a string literal\n- unary `-`\n- tuples, lists, records and variants whose parts are constant expressions\n- other constants\nArithmetic, a call, a field access, a block, an `if`, a closure, a function named as a value or anything else in it is E0326, constant's value isn't a constant expression. The error is at the first part, in evaluation order, that a constant expression can't hold.\nOutside `std` (declarations.native-items), a hole is no exception, so `const LATER: i64 = ?` is E0326. E0326 is an error of the constant's types, after which its hole gets no warning (errors.phases).", tier: "core", phase: "types", help: "A constant is built from literals and other constants, with no arithmetic and no calls. Write the value itself, as `600`, or compute it in a function.", span: "The first part of the value, in evaluation order, that a constant expression can't hold.", retired: false, examples: &[Example { wrong: "const TIMEOUT: i64 = 10 * 60\n", line: 1, right: "const TIMEOUT: i64 = 600\n" }] });
/// constants in a cycle
pub const E0327: Code = Code(&Entry { code: "E0327", title: "constants in a cycle", reference: "declarations.constant-cycles", rule: "Constants must not refer to one another in a cycle, nor a constant to itself. Each cycle is one error, E0327, constants in a cycle, at the last of the declarations of its constants.", tier: "core", phase: "items", help: "A constant's value can't depend on itself. Give one of them a value that doesn't refer back.", span: "The name of the last constant of the cycle (errors.several-places).", retired: false, examples: &[Example { wrong: "const WIDTH: i64 = HEIGHT\nconst HEIGHT: i64 = WIDTH\n", line: 2, right: "const WIDTH: i64 = 80\nconst HEIGHT: i64 = WIDTH\n" }] });
/// float in a pattern
pub const E0328: Code = Code(&Entry { code: "E0328", title: "float in a pattern", reference: "patterns.floats", rule: "Only `_` and a binding match a float, and no literal pattern is a float. An integer literal matched against a float is E0328, float in a pattern. So is a constant whose type can hold a float, itself or in its elements, fields or payloads. A constant of type `f64` is one, and so is a constant of a record with an `f64` field.", tier: "core", phase: "types", help: "Floats don't compare reliably for equality, so a pattern can't match one. Compare it with `<` or `<=` in an `if`, or in a guard.", span: "The pattern.", retired: false, examples: &[Example { wrong: "fn describe(temperature: f64) -> str {\n  match temperature {\n    0 => \"freezing\"\n    _ => \"not freezing\"\n  }\n}\n", line: 3, right: "fn describe(temperature: f64) -> str {\n  if temperature <= 0.0 { \"freezing\" } else { \"not freezing\" }\n}\n" }] });
/// patterns that don't cover every value
pub const E0329: Code = Code(&Entry { code: "E0329", title: "patterns that don't cover every value", reference: "patterns.non-exhaustive-matches", rule: "Arms that cover every value of their type are exhaustive. A `match` whose arms aren't exhaustive is E0329, patterns that don't cover every value, at the `match`, and the diagnostic names one missing pattern as a witness. So are the arms of a `catch` that don't cover its error type (effects.catch-syntax), at the `try`, so `catch {}` handles only `Never`.\nA pattern on a part of the value whose type is the error type covers that part. So a mistake in a type gives no further diagnostic in the matches on it. The check runs with the analyses of a body, once its types have no error (errors.phases).", tier: "core", phase: "analyses", help: "A `match` covers every value of its type. Add an arm for each case that the message names, or a last `_ => …` arm.", span: "The `match` or the `try`.", retired: false, examples: &[Example { wrong: "type Status = | Pending | Paid | Shipped\n\nfn label(s: Status) -> str {\n  match s {\n    Pending => \"pending\"\n    Paid => \"paid\"\n  }\n}\n", line: 4, right: "type Status = | Pending | Paid | Shipped\n\nfn label(s: Status) -> str {\n  match s {\n    Pending => \"pending\"\n    Paid => \"paid\"\n    Shipped => \"shipped\"\n  }\n}\n" }] });
/// trait function or constant named without a type
pub const E0330: Code = Code(&Entry { code: "E0330", title: "trait function or constant named without a type", reference: "traits.functions-without-self", rule: "A trait may declare functions that take no `self`, and constants, `const NAME: T`. Each may have a default, `= expr`, or not, and an impl holds them as it holds methods (traits.impl-members). They are named on a type:\n- `T.empty()` and `T.ZERO` on a type parameter bounded by the trait\n- `i64.empty()` and `i64.ZERO` on a type with an impl, found as traits.qualified-calls finds `Type.m`\n- `Self.empty()` in the trait's own members\n`T.empty` is a function value, as `Type.m` is. `Trait.f(…)` for a function without `self`, and `Trait.NAME`, are E0330, trait function or constant named without a type, whose fix writes the type. No call is resolved from the type it is expected to have (traits.no-overloading). In a module that names `std.meta`, `T.shape()` and `T.name()` are found after these (meta.shape-and-name). Trait functions without `self` and trait constants are part of the advanced tier.", tier: "advanced", phase: "types", help: "A trait's function without `self` is named on a type, as `Count.empty()`, since the trait alone doesn't say which impl to call.", span: "The path that names the trait.", retired: false, examples: &[Example { wrong: "trait Empty {\n  fn empty() -> Self\n}\n\ntype Count = { n: i64 }\n\nimpl Empty for Count {\n  fn empty() -> Count { Count { n: 0 } }\n}\n\nfn fresh() -> Count { Empty.empty() }\n", line: 11, right: "trait Empty {\n  fn empty() -> Self\n}\n\ntype Count = { n: i64 }\n\nimpl Empty for Count {\n  fn empty() -> Count { Count { n: 0 } }\n}\n\nfn fresh() -> Count { Count.empty() }\n" }] });
/// constant with a written `Eq` in a pattern
pub const E0331: Code = Code(&Entry { code: "E0331", title: "constant with a written `Eq` in a pattern", reference: "patterns.constants-with-written-eq", rule: "A constant is not a pattern when its type holds, at any depth, a type whose `Eq` impl the program writes. That type may be the constant's type itself, one of its type arguments, or the type of one of its fields or payloads. A constant like this used as a pattern is E0331, constant with a written `Eq` in a pattern. The rule goes by the type, not the value: with the `Eq` of `Name` written, `const NOBODY: Option<Name> = None` is not a pattern either. A guard may compare such a constant instead, as in `n if n == NOBODY`.", tier: "core", phase: "types", help: "A pattern compares values field by field, which could disagree with the `eq` you wrote. Compare the constant with `==` in an `if` or a guard.", span: "The pattern.", retired: false, examples: &[Example { wrong: "type Money = { cents: i64 }\n\nimpl Eq for Money {\n  fn eq(self, other: Money) -> bool { self.cents == other.cents }\n}\n\nconst FREE: Money = Money { cents: 0 }\n\nfn label(price: Money) -> str {\n  match price {\n    FREE => \"free\"\n    _ => \"paid\"\n  }\n}\n", line: 11, right: "type Money = { cents: i64 }\n\nimpl Eq for Money {\n  fn eq(self, other: Money) -> bool { self.cents == other.cents }\n}\n\nconst FREE: Money = Money { cents: 0 }\n\nfn label(price: Money) -> str {\n  if price == FREE { \"free\" } else { \"paid\" }\n}\n" }] });
/// property that isn't a closure with typed parameters
pub const E0332: Code = Code(&Entry { code: "E0332", title: "property that isn't a closure with typed parameters", reference: "tests.property-form", rule: "A property must be a closure literal (expressions.closures) with at least one parameter. Each parameter is a pattern that a closure's parameter may be, with its type written, as `|xs: List<i64>| …` or `|(a, b): (i64, str)| …`. Any other expression, and a closure with no parameter, is E0332, property that isn't a closure with typed parameters, at the expression. A parameter without a type is E0332 at the parameter. So is a parameter marked `inout`, which takes no generated value (expressions.inout-closure-parameters). A property with E0332 reports nothing else.", tier: "core", phase: "types", help: "A property is a closure with typed parameters that returns a `bool`, as `/// prop: |xs: List<i64>| …`, since `stilt test` generates values of each type. A check without parameters is an example, `/// ex:`.", span: "The property's expression, or the parameter without a type or marked `inout`.", retired: false, examples: &[Example { wrong: "/// prop: |xs| reverse(reverse(xs)) == xs\nfn reverse(xs: List<i64>) -> List<i64> { xs.fold([], |acc, x| [x].concat(acc)) }\n", line: 1, right: "/// prop: |xs: List<i64>| reverse(reverse(xs)) == xs\nfn reverse(xs: List<i64>) -> List<i64> { xs.fold([], |acc, x| [x].concat(acc)) }\n" }] });
/// parameter type that can't be generated
pub const E0333: Code = Code(&Entry { code: "E0333", title: "parameter type that can't be generated", reference: "tests.generable-types", rule: "Each parameter's type must be generable, or it is E0333, parameter type that can't be generated, at the parameter's type. A type holds its elements, its fields, its payloads, a list's element type and a map's key and value types, and what those hold in turn. A type is generable when all three of these are true:\n- it and every type it holds are built from `bool`, the numeric types (numbers.numeric-types), `str` and `()`, with tuples, lists, maps, records and variant types. The records and variant types may be those of the prelude or those that any module declares;\n- neither it nor any type it holds is a function type, a type with no values (patterns.types-without-values) or a `Map<K, V>` whose `K` doesn't implement both `Eq` and `Hash` (std.map-key-bounds). `Never` and `type Loop = | Loop(Loop)` are types with no values;\n- it holds finitely many types (tests.growth-test).", tier: "core", phase: "types", help: "`stilt test` can't generate functions, values of a type that has none, or maps whose keys aren't `Eq` and `Hash`. Take values that it can generate, and build the rest inside the property.", span: "The parameter's type.", retired: false, examples: &[Example { wrong: "/// Applies `f` twice.\n/// prop: |f: fn(i64) -> i64, x: i64| twice(f, x) == f(f(x))\nfn twice(f: fn(i64) -> i64, x: i64) -> i64 { f(f(x)) }\n", line: 2, right: "/// Applies `f` twice.\n/// prop: |x: i64| twice(|n| n +% 1, x) == x +% 2\nfn twice(f: fn(i64) -> i64, x: i64) -> i64 { f(f(x)) }\n" }] });
/// member type that names nothing
pub const E0334: Code = Code(&Entry { code: "E0334", title: "member type that names nothing", reference: "traits.member-types", rule: "`C.Item` is a member type when `C` is a type parameter of the function or of its impl block, and `Item` is a parameter of the trait of a bound of `C`. It is the type that the impl of that trait for the type of `C` gives `Item`. Where the bound gives the argument, the member type is that argument, so under `C: Collection<i64>`, `C.Item` is `i64`.\nA member type is E0334, member type that names nothing, when its `C` isn't a type parameter, or when no trait of the bounds of `C` has a parameter `Item`. A member type that the traits of two of the bounds have is E0335, ambiguous member type. Its fix names the argument with a generic of the function, as in `C: Collection<T>`. Member types are part of the advanced tier.", tier: "advanced", phase: "types", help: "A member type such as `C.Item` names a parameter of a trait that bounds `C`. Check the name against the trait's parameters.", span: "The member type.", retired: false, examples: &[Example { wrong: "trait Collection<Item> {\n  fn at(self, i: i64) -> Option<Item>\n}\n\nfn first<C: Collection>(c: C) -> Option<C.Key> { None }\n", line: 5, right: "trait Collection<Item> {\n  fn at(self, i: i64) -> Option<Item>\n}\n\nfn first<C: Collection>(c: C) -> Option<C.Item> { c.at(0) }\n" }] });
/// ambiguous member type
pub const E0335: Code = Code(&Entry { code: "E0335", title: "ambiguous member type", reference: "traits.member-types", rule: "`C.Item` is a member type when `C` is a type parameter of the function or of its impl block, and `Item` is a parameter of the trait of a bound of `C`. It is the type that the impl of that trait for the type of `C` gives `Item`. Where the bound gives the argument, the member type is that argument, so under `C: Collection<i64>`, `C.Item` is `i64`.\nA member type is E0334, member type that names nothing, when its `C` isn't a type parameter, or when no trait of the bounds of `C` has a parameter `Item`. A member type that the traits of two of the bounds have is E0335, ambiguous member type. Its fix names the argument with a generic of the function, as in `C: Collection<T>`. Member types are part of the advanced tier.", tier: "advanced", phase: "types", help: "Two bounds give the type parameter a member of that name. Name the one you mean with a generic, as `C: Collection<T>`, and write `T`.", span: "The member type.", retired: false, examples: &[Example { wrong: "trait Collection<Item> {\n  fn at(self, i: i64) -> Option<Item>\n}\n\ntrait Stream<Item> {\n  fn next(self) -> Option<Item>\n}\n\nfn first<C: Collection + Stream>(c: C) -> Option<C.Item> { None }\n", line: 9, right: "trait Collection<Item> {\n  fn at(self, i: i64) -> Option<Item>\n}\n\ntrait Stream<Item> {\n  fn next(self) -> Option<Item>\n}\n\nfn first<C: Collection<T> + Stream, T>(c: C) -> Option<T> { None }\n" }] });
/// `where` bound that isn't on a member type
pub const E0336: Code = Code(&Entry { code: "E0336", title: "`where` bound that isn't on a member type", reference: "traits.where", rule: "A `where` clause bounds member types, as in `where C.Item: Ord + Show, D.Key: Hash`. It stands in one of two places:\n- after a function's signature, on the line where the signature ends and before its `without` clause (syntax.limit-clauses)\n- after an impl's type, before its `{`\nA function of an inherent block may bound the member types of the block's parameters. Each bound of a `where` clause is checked as a bound beside a parameter is. Where a bound's argument fixes the member type, as in `C: Collection<f64> where C.Item: Hash`, the fixed type must meet the bound, or the bound is E0318, unsatisfied bound.\nEach of these is E0336, `where` bound that isn't on a member type:\n- a bound in a `where` clause on anything but a member type, whose fix moves it beside its parameter\n- a `where` clause on a function of a trait or of a trait impl, which has the trait's signature and can't bound what the trait leaves open\n`where` is a keyword (lexical.keywords), and a `where` clause is part of the advanced tier.", tier: "advanced", phase: "types", help: "A type parameter's bound goes beside it, as `<T: Show>`. A `where` clause bounds only member types, such as `C.Item`.", span: "The bounded type, or the `where` keyword on a function of a trait or a trait impl.", retired: false, examples: &[Example { wrong: "fn shown<T>(x: T) -> str where T: Show { \"{x}\" }\n", line: 1, right: "fn shown<T: Show>(x: T) -> str { \"{x}\" }\n" }] });
/// type of the wrong kind
pub const E0337: Code = Code(&Entry { code: "E0337", title: "type of the wrong kind", reference: "traits.constructor-traits", rule: "A trait whose members write `Self` applied to type arguments, as `Self<A>`, is a constructor trait. It abstracts over a type constructor that takes that many type arguments, its arity. Each `Self` in it takes the same number of arguments, so `Self` alone, or with another number of them, is E0337, type of the wrong kind. Constructor traits are part of the advanced tier.", tier: "advanced", phase: "types", help: "A constructor trait's parameter stands for a generic type, so it is written with its type arguments, as `F<i64>`.", span: "The type, or the bound that mixes kinds.", retired: false, examples: &[Example { wrong: "trait Mappable {\n  fn transform<A, B>(self: Self<A>, f: fn(A) -> B) -> Self<B>\n}\n\nfn size<F: Mappable>(xs: F) -> i64 { 0 }\n", line: 5, right: "trait Mappable {\n  fn transform<A, B>(self: Self<A>, f: fn(A) -> B) -> Self<B>\n}\n\nfn size<F: Mappable>(xs: F<i64>) -> i64 { 0 }\n" }] });
/// receiver's type written or missing
pub const E0338: Code = Code(&Entry { code: "E0338", title: "receiver's type written or missing", reference: "traits.receiver-types", rule: "Each method of a constructor trait writes the type of its receiver, as `self: Self<A>` or `inout self: Self<A>`, and that type is `Self` applied to types. A method of an impl writes it with the impl's constructor, as `self: Option<A>` (traits.constructor-impls). Each of these is E0338, receiver's type written or missing:\n- a method of a constructor trait whose receiver's type isn't written\n- a receiver with a written type anywhere but in a constructor trait and its impls", tier: "advanced", phase: "items", help: "A method's receiver is written `self`, without a type. Only a constructor trait's methods write one, as `self: Self<A>`.", span: "The `self` parameter.", retired: false, examples: &[Example { wrong: "trait Named {\n  fn name(self: Self) -> str\n}\n", line: 2, right: "trait Named {\n  fn name(self) -> str\n}\n" }] });
/// type parameter of a function type that nothing uses
pub const E0339: Code = Code(&Entry { code: "E0339", title: "type parameter of a function type that nothing uses", reference: "polymorphism.function-types", rule: "A function type may declare type parameters, with bounds, after `fn`, as in `fn<T: Show, U>(T, U) -> str / row`. It is then a polymorphic function type. Its type parameters are uppercase names, as a function's are, and each is in scope in the function type alone. Each must appear in its parameter types or its result (E0339). A type parameter with the name of one already in scope, the enclosing function's or impl block's, is E0208. These rules also hold for a polymorphic function type:\n- It declares no row variable and no value parameter.\n- None of its type parameters is a pack (variadics.packs).\n- It declares no member types (traits.member-types), so each of its bounds is a trait given all its arguments.\n- A constructor trait bounds none of its parameters (E0337).\nThis is part of the advanced tier (polymorphism.advanced-tier).", tier: "advanced", phase: "types", help: "A function type's type parameter appears in its parameters or its result, so that each call can tell what it is. Delete the one that doesn't.", span: "The type parameter.", retired: false, examples: &[Example { wrong: "fn first(f: fn<T, U>(T) -> T) -> i64 { f(1) }\n", line: 1, right: "fn first(f: fn<T>(T) -> T) -> i64 { f(1) }\n" }] });
/// polymorphic function type out of place
pub const E0340: Code = Code(&Entry { code: "E0340", title: "polymorphic function type out of place", reference: "polymorphism.placement", rule: "A polymorphic function type may be the type of one of these, and nowhere else:\n- a function's parameter;\n- a parameter of a function type;\n- a record field;\n- a variant's payload field.\nAnywhere else it is E0340, polymorphic function type out of place. So a type argument, as in `List<fn<T>(T) -> T>`, is E0340, and so are a function's result, a local's or a closure parameter's annotation, a constant's type and a tuple's element. A value of a polymorphic function type can be passed and stored in a field, but never put in a collection.", tier: "advanced", phase: "types", help: "A generic function type is only the type of a parameter or a field. Return a function of known types, as `fn(i64) -> i64`, or make the outer function generic.", span: "The polymorphic function type.", retired: false, examples: &[Example { wrong: "fn make() -> fn<T>(T) -> T { |x| x }\n", line: 1, right: "fn make() -> fn(i64) -> i64 { |x| x }\n" }] });
/// open record type out of place
pub const E0341: Code = Code(&Entry { code: "E0341", title: "open record type out of place", reference: "records.open-parameter-types", rule: "A parameter's type may be an open record type, `{ f: T, .. }`. It stands for a hidden, unnamed type parameter of the function with that record bound: `fn greet(p: { name: str, .. })` means `fn greet<P: { name: str, .. }>(p: P)`. Each open type written is its own type parameter. An open record type anywhere else is E0341, open record type out of place. That includes a field, a result, a type argument, a local's annotation and a parameter of a function type. The fix names a type parameter with the bound.", tier: "advanced", phase: "types", help: "A record bound ends with `..`, as `P: { name: str, .. }`, and an open record type is only a parameter's type. Elsewhere, name a type parameter with that bound.", span: "The record bound or the open record type.", retired: false, examples: &[Example { wrong: "fn name_of<P: { name: str }>(p: P) -> str { p.name }\n", line: 1, right: "fn name_of<P: { name: str, .. }>(p: P) -> str { p.name }\n" }] });
/// operation on a tuple whose arity isn't known
pub const E0342: Code = Code(&Entry { code: "E0342", title: "operation on a tuple whose arity isn't known", reference: "variadics.pack-tuples", rule: "A pack tuple is a value whose type is a tuple type with a spread. It may be passed, returned, stored and copied as a tuple is. It may be compared or shown as a tuple is when its elements meet `Eq` or `Show` through the pack's bounds (traits.structural-impls). Its arity isn't known in the body. So a pattern that destructures it, `.0` on it, `for` over it and indexing it are E0342.", tier: "advanced", phase: "types", help: "A tuple whose type spreads a pack has a number of elements that the body doesn't know, so it is passed whole or mapped with a spread, never indexed or matched.", span: "The pattern, the element access or the `for`.", retired: false, examples: &[Example { wrong: "fn first<..Ts>(xs: (..Ts)) -> i64 { xs.0 }\n", line: 1, right: "fn first<A, B>(xs: (A, B)) -> A { xs.0 }\n" }] });
/// malformed spread
pub const E0343: Code = Code(&Entry { code: "E0343", title: "malformed spread", reference: "variadics.type-spreads", rule: "A pack is written only spread, as `..T`, where `T` is a type that names one or more packs. A spread stands among the elements of a tuple type or the parameters of a function type, as in `(..Ts)`, `(..List<Ts>, i64)` and `fn(..Ts) -> R`. A spread names exactly one pack, perhaps more than once. It stands for one element for each of the pack's elements, with the pack replaced by that element. So `(..List<Ts>)` at `Ts = (i64, str)` is `(List<i64>, List<str>)`, and `(..Ts, ..Us)` places two packs side by side. A pack written outside a spread, a spread that names no pack or two, and a spread inside a spread are E0343, malformed spread. A tuple type with a spread and no other element is the tuple of its elements. So `(..Ts)` at one element `T` is `(T,)`, and at none is `()`.", tier: "advanced", phase: "types", help: "A spread maps a tuple whose type spreads a pack, once per element, as `[..lists.len()]`. It names exactly one such tuple, and can't stand inside another spread.", span: "The pack, the spread, or the tuple named.", retired: false, examples: &[Example { wrong: "fn sizes<..Ts>(lists: (..List<Ts>)) -> List<i64> { [..1] }\n", line: 1, right: "fn sizes<..Ts>(lists: (..List<Ts>)) -> List<i64> { [..lists.len()] }\n" }] });
/// pack out of place
pub const E0344: Code = Code(&Entry { code: "E0344", title: "pack out of place", reference: "variadics.packs", rule: "`..Ts` among a function's generics, or among a type's parameters, declares a pack: a type parameter that stands for a sequence of zero or more types, its elements. A function may declare several packs. A type may declare at most one, as its last parameter (E0344), so the arguments of `Row<i64, str, bool>` after the others are the pack's. A pack may take bounds, as `..Ts: Show`, which each element meets (traits.bounds). A trait's parameters, a constructor trait's `Self` and a polymorphic function type's parameters are never packs (E0344). This is part of the advanced tier (variadics.advanced-tier).", tier: "advanced", phase: "types", help: "Only the last type parameter of a function or a type can be a pack, and a trait's parameters never are.", span: "The pack.", retired: false, examples: &[Example { wrong: "trait Wrap<..Ts> {}\n", line: 1, right: "trait Wrap<T> {}\n" }] });
/// value parameter of a type that can't be compared
pub const E0345: Code = Code(&Entry { code: "E0345", title: "value parameter of a type that can't be compared", reference: "generics.value-parameters", rule: "A function's generics, a type's parameters and an impl's generics may hold value parameters, beside type parameters and, for a function, row variables (declarations.function-declarations). A value parameter is written `name: T`, as `n: i64`. Its name is a `lower` identifier, as every value's is (lexical.case), so `<n: i64>` is a value parameter and `<e>` a row variable. As for type parameters, the names of one list of generics must be distinct, and so must those of an impl's generics and its members' generics (E0208). A value parameter's type is an integer type or `bool`. Any other type, as `f64`, `str` or a declared type, is E0345 at the type. This is part of the meta tier (generics.meta-tier).", tier: "meta", phase: "items", help: "Two types are one type when their value arguments are equal, so a value parameter is an integer or a `bool`, which compare exactly. Use an integer, scaled if you need fractions.", span: "The value parameter's type.", retired: false, examples: &[Example { wrong: "type Scaled<k: f64> = { value: f64 }\n", line: 1, right: "type Scaled<k: i64> = { value: f64 }\n" }] });
/// value parameter that nothing determines
pub const E0346: Code = Code(&Entry { code: "E0346", title: "value parameter that nothing determines", reference: "generics.value-parameters-determined", rule: "A function's value parameter must appear, outside every row, in the type of one of its parameters or in its result type. One that appears in neither is E0346 at the parameter, unless its own type is the error type or one that E0345 reports, which leaves it the error type (errors.error-type): so `<x: f64>` is E0345 alone. Appearing is enough here. A use that still leaves it undetermined is E0312 at the use, as for a type parameter, as a closure literal given for `g: fn(Array<i64, n>)` does. An impl's type is its constructor applied to the impl's parameters, value and type, each once (traits.impl-blocks). So `impl Mod<7>` and `impl<p: u64> Mod<p, p>` are E0302, as `impl List<i64>` is, and so is an impl's value parameter that its type doesn't name. A type is always written with its arguments (declarations.type-arguments), so a type's value parameter may appear in none of its fields, as `p` doesn't in `type Mod<p: u64> = { value: u64 }`.", tier: "meta", phase: "items", help: "A call writes no value arguments, so a value parameter is found from the types of the arguments or of the result. Use it in one of them, as in `array.Array<i64, n>`.", span: "The value parameter.", retired: false, examples: &[Example { wrong: "fn zeros<n: i64>() -> i64 { n }\n", line: 1, right: "use std.array\n\nfn count<n: i64>(a: array.Array<i64, n>) -> i64 { n }\n" }] });
/// invalid value argument
pub const E0347: Code = Code(&Entry { code: "E0347", title: "invalid value argument", reference: "generics.value-argument-names", rule: "Whether an argument is for a type parameter or a value parameter is read from the declaration of its constructor. An `Upper` path there is looked up as a constant for a value parameter, and as a type for a type parameter. A `lower` name is looked up among the primitive type names, then the value parameters in scope, then every other name in scope where the type is written, locals included. A name found anywhere but where its position needs it is E0347 at the argument. These are such names:\n- for a value parameter, a type, as in `Mod<i64>`, a local, a function or the variable of a `comptime for` (meta.staged-loops);\n- for a type parameter, a literal, a constant, a value parameter, a function, a local or a module, as in `List<3>`, `List<PRIME>`, `List<n>` or `List<print>`.\nA name found nowhere is E0211.", tier: "meta", phase: "types", help: "A value argument is a literal, a constant or a value parameter, never a type, a local or a computation, and an array's size is 0 or more.", span: "The argument.", retired: false, examples: &[Example { wrong: "use std.array\n\nfn empty(a: array.Array<i64, -1>) -> i64 { a.len() }\n", line: 3, right: "use std.array\n\nfn empty(a: array.Array<i64, 0>) -> i64 { a.len() }\n" }] });
/// binding named like a value parameter
pub const E0348: Code = Code(&Entry { code: "E0348", title: "binding named like a value parameter", reference: "generics.value-parameters-in-body", rule: "A value parameter's name is an immutable value of its type, as a constant is, in the body of its function and in the members of its impl. `0..n`, `n * 2` and `f(n)` read it. It hides an item of the same name, as a parameter does (expressions.shadowing). A binding in those bodies named as a value parameter in scope is E0348 at the binding. That holds for a parameter, a `let`, a `var`, a pattern's variable and a closure's parameter.", tier: "meta", phase: "types", help: "A type written after this binding would still mean the value parameter, not the binding. Give the binding another name.", span: "The binding's name.", retired: false, examples: &[Example { wrong: "use std.array\n\nfn last<n: i64>(a: array.Array<i64, n>) -> i64 {\n  let n = n - 1\n  a[n]\n}\n", line: 4, right: "use std.array\n\nfn last<n: i64>(a: array.Array<i64, n>) -> i64 {\n  let i = n - 1\n  a[i]\n}\n" }] });
/// staging annotation on a value known only at run time
pub const E0349: Code = Code(&Entry { code: "E0349", title: "staging annotation on a value known only at run time", reference: "meta.not-static", rule: "Nothing else is static. Among the forms that aren't are a function's parameter, a `var`, a closure, a call through a function value, and a call whose row isn't empty, as `print(…)` or `fs.read(…)`. A block, an `if`, a `match`, a loop, `try` and `else` aren't static either.\nAn annotated part that isn't static is E0349, staging annotation on a value known only at run time. It is reported once, at its first part that isn't static in evaluation order (values.left-to-right). In that order, an expression's operands, callee, receiver and arguments come before the expression that holds them. So in `0..f(x)` with a parameter `x`, the error is at `x`, and in `print(1)` it is at the call. A block, an `if`, a `match`, a loop, a closure, `try` and `else` are reported whole, without looking inside them. The message names the reason: a parameter is known only at run time, a `var` may change, a call performs the effects of its row, and the other forms run code.", tier: "meta", phase: "analyses", help: "`comptime` asserts that a value is known while compiling, which this one isn't. Delete `comptime`, which changes nothing the program does, or make the value a value parameter.", span: "The first part of the annotated expression that isn't static.", retired: false, examples: &[Example { wrong: "fn report(n: i64) / io {\n  comptime if n > 0 { print(\"positive\") }\n}\n", line: 2, right: "fn report(n: i64) / io {\n  if n > 0 { print(\"positive\") }\n}\n" }] });
/// type without a shape given to a function that reflects
pub const E0350: Code = Code(&Entry { code: "E0350", title: "type without a shape given to a function that reflects", reference: "meta.types-without-shape", rule: "A function type, a handler type, and a native type of `std` to which meta.shapes gives no case have no shape. `View`, `Iter`, `Lazy`, `Shared`, `Task` and `Scope` are among those native types.\nA function that reflects on `T` is instantiated by a call or by naming it as a value. There, the type given for `T` must have a shape, unless it has an impl of one of the function's guards. When the function reflects on the parts of `T`, each type that `T`'s fields, elements and payloads hold, at any depth, must have a shape too. These types are walked depth first in the order of meta.shapes, each type once, skipping a type with an impl of a guard and what it holds.\nThe first type that fails is E0350, type without a shape given to a function that reflects. It is reported once, at the first argument whose type holds it, or at the call or the name when none does. Its message names that type, the types that hold it, and the chain of functions that reflect, from the one instantiated to the one that names `T.shape()`.", tier: "meta", phase: "analyses", help: "A function that reflects reads the shape of each type it reaches, and function types, handlers and native types such as `Shared` have none. Leave such fields out, or give the type an impl of a trait the function checks first.", span: "The first argument whose type holds the type without a shape, or the call or the name when none does.", retired: false, examples: &[Example { wrong: "use std.meta\n\ntype Job = { name: str, run: fn() -> i64 }\n\nfn leaves<T>(value: T) -> i64 {\n  match T.shape() {\n    Record(fields) => {\n      var total = 0\n      for f in fields { total += leaves(f.get(value)) }\n      total\n    }\n    _ => 1\n  }\n}\n\nfn main() / io {\n  let job = Job { name: \"build\", run: || 1 }\n  print(\"{leaves(job)}\")\n}\n", line: 18, right: "use std.meta\n\ntype Job = { name: str, tries: i64 }\n\nfn leaves<T>(value: T) -> i64 {\n  match T.shape() {\n    Record(fields) => {\n      var total = 0\n      for f in fields { total += leaves(f.get(value)) }\n      total\n    }\n    _ => 1\n  }\n}\n\nfn main() / io {\n  let job = Job { name: \"build\", tries: 1 }\n  print(\"{leaves(job)}\")\n}\n" }] });
/// value of a fresh type leaving its arm
pub const E0351: Code = Code(&Entry { code: "E0351", title: "value of a fresh type leaving its arm", reference: "meta.leaving-arm", rule: "A value whose type contains a fresh type can't leave its arm. Each of these, when its type contains a fresh type, is E0351, value of a fresh type leaving its arm, at the expression:\n- an arm's value;\n- a value assigned or passed `inout` to a variable declared outside the arm;\n- a value returned or raised, even where a `try` in the arm catches it;\n- any expression whose type would decide a type that inference left open outside the arm, as `acc.push(x)` does for a `var acc = []` declared before the arm.\nAgainst a type already known outside the arm, as an arm's value where `str` is expected, a fresh type is E0311, mismatched types (types.mismatch). It is E0311 too against the type of a literal declared outside, as `var n = 1`, which only a number type can be (numbers.literal-defaults).", tier: "meta", phase: "types", help: "A value whose type is fresh to a reflecting arm can't leave it, since no code outside can name that type. Compute what you need inside the arm, such as a count, and give that.", span: "The expression whose value would leave.", retired: false, examples: &[Example { wrong: "use std.meta\n\nfn elements<T>(value: T) -> i64 {\n  var acc = []\n  match T.shape() {\n    List(c) => { for x in c.get(value) { acc.push(x) } }\n    _ => {}\n  }\n  acc.len()\n}\n\nfn main() / io {\n  print(\"{elements([1, 2])}\")\n}\n", line: 6, right: "use std.meta\n\nfn elements<T>(value: T) -> i64 {\n  match T.shape() {\n    List(c) => c.get(value).len()\n    _ => 0\n  }\n}\n\nfn main() / io {\n  print(\"{elements([1, 2])}\")\n}\n" }] });
/// exported function C can't call
pub const E0352: Code = Code(&Entry { code: "E0352", title: "exported function C can't call", reference: "c.exported-signatures", rule: "An exported function takes and returns only these types, each passed as C passes the type beside it:\n- `i8`, `i16`, `i32` and `i64` as `int8_t` to `int64_t`;\n- `u8` to `u64` as `uint8_t` to `uint64_t`;\n- `f32` and `f64` as `float` and `double`;\n- `bool` as `bool`;\n- `()`, as a result only, as `void`.\nIt has no type, value or effect-row parameter, no `inout` or `escaping` parameter, and no result of type `Never`. Its row has no `raise<E>`, no `async` and no user-defined effect. It may perform `io` and its capabilities (facts.capabilities). Any other signature is E0352, exported function C can't call, once for each part that C can't take. It is reported at the name of an `inout` or `escaping` parameter, at the type of another parameter or of the result, at a generic, and at an element of the row.", tier: "core", phase: "types", help: "C calls an exported function, so it takes and returns only numbers and `bool`, and its name is a C symbol of its own. Keep the rest of the code inside Stilt.", span: "The part of the signature that C can't take, or the name.", retired: false, examples: &[Example { wrong: "/// The checksum of a line of text.\npub extern fn checksum(line: str) -> u32 {\n  line.len().to_u32() else 0\n}\n", line: 2, right: "/// The checksum of a line of text of `len` bytes.\npub extern fn checksum(len: u64) -> u32 {\n  len.to_u32() else 0\n}\n" }] });
/// type C can't take
pub const E0353: Code = Code(&Entry { code: "E0353", title: "type C can't take", reference: "c.types-c-takes", rule: "A foreign function's parameters and result have the types of c.exported-signatures, or one of three more:\n- `c.Ptr<T>`, from the module `std.c` (c.module-std-c), an address that C reads or writes, for `T` one of those types, `()` for `void`, or another `c.Ptr`;\n- `c.Str`, from `std.c`, a NUL-terminated string, C's `const char *`;\n- `()`, as a result only.\nAny other type is E0353, type C can't take, at the type.", tier: "systems", phase: "types", help: "A foreign function takes what C passes: numbers, `bool`, a `c.Ptr<T>` of them and a `c.Str`. Lend a list's elements with `with_ptr`, as a `c.Ptr<u8>`.", span: "The part of the signature that C can't take: the type, the generic's name, `self`, the parameter's name or the row's element; or the call whose `T` C can't hold.", retired: false, examples: &[Example { wrong: "use std.c\n\n/// zlib's CRC-32 of `len` bytes from `buf`, continuing `crc`.\npub extern fn crc32(crc: u64, buf: List<u8>, len: u32) -> u64\n", line: 4, right: "use std.c\n\n/// zlib's CRC-32 of `len` bytes from `buf`, continuing `crc`.\npub extern fn crc32(crc: u64, buf: c.Ptr<u8>, len: u32) -> u64\n" }] });
/// `inout` argument marked wrongly
pub const E0400: Code = Code(&Entry { code: "E0400", title: "`inout` argument marked wrongly", reference: "expressions.inout-arguments", rule: "An argument to an `inout` parameter must be marked `inout` at the call site, as in `normalize(inout v)`, and an argument to any other parameter must not be (E0400). The receiver of a method whose `self` is `inout` is not marked. Both must be places (expressions.places), so `bump(inout 5)` and `[3, 1, 2].push(4)` are E0401.", tier: "core", phase: "types", help: "An argument for an `inout` parameter is marked `inout` at the call, as `bump(inout count)`, so that a change to it is visible there; no other argument is.", span: "The argument.", retired: false, examples: &[Example { wrong: "fn bump(inout count: i64) { count += 1 }\n\nfn twice(inout count: i64) {\n  bump(inout count)\n  bump(count)\n}\n", line: 5, right: "fn bump(inout count: i64) { count += 1 }\n\nfn twice(inout count: i64) {\n  bump(inout count)\n  bump(inout count)\n}\n" }] });
/// not a place
pub const E0401: Code = Code(&Entry { code: "E0401", title: "not a place", reference: "modes.places", rule: "A place is a variable followed by zero or more fields, tuple fields and indexes: `.field`, `.0` or `[index]`. A call of a projection is a place too, rooted in the call (projections.call-is-place). So is `v[i]` for a binding `v` of a view of a list (projections.places-through-views). A field read through an `Option` is not a place, and neither is a field or an element of one (types.option-field-not-place). A place is required in each of these positions:\n- the target of an assignment;\n- an `inout` argument;\n- the receiver of a method that takes `inout self`;\n- the operand of a `yield`.\nWhere a place is required, anything else is E0401, not a place (expressions.places).", tier: "core", phase: "types", help: "Only a variable, a field or an element can be assigned or passed `inout`. Put the value in a `var` first, and pass that.", span: "The expression that isn't a place.", retired: false, examples: &[Example { wrong: "fn bump(inout count: i64) { count += 1 }\n\nfn next(count: i64) -> i64 {\n  bump(inout count + 1)\n  count\n}\n", line: 4, right: "fn bump(inout count: i64) { count += 1 }\n\nfn next(count: i64) -> i64 {\n  var n = count\n  bump(inout n)\n  n\n}\n" }] });
/// overlapping `inout` arguments
pub const E0402: Code = Code(&Entry { code: "E0402", title: "overlapping `inout` arguments", reference: "modes.overlapping-inout", rule: "Two overlapping `inout` arguments of one call are E0402, overlapping `inout` arguments, at the later of the two places. So is an `inout` argument that overlaps an `inout self` receiver. So `swap(inout a, inout a)`, `f(inout a.b, inout a)`, and `a.f(inout a.b)` where `f` takes `inout self`, are each E0402. Other arguments are read before the call starts, so `xs.push(xs.len())`, `xs.push(xs[0])` and `f(inout a, a)` are accepted. In the last one, `f` receives the value `a` had before the call.", tier: "core", phase: "analyses", help: "Two places that one call modifies can't overlap, since the result would depend on which one is written back last. Use a method made for it, such as `xs.swap(i, j)`, or copy one of them first.", span: "The later of the two overlapping places.", retired: false, examples: &[Example { wrong: "fn swap(inout a: i64, inout b: i64) {\n  let t = a\n  a = b\n  b = t\n}\n\nfn mixed(inout xs: List<i64>) { swap(inout xs[0], inout xs[1]) }\n", line: 7, right: "fn mixed(inout xs: List<i64>) { xs.swap(0, 1) }\n" }] });
/// modifying what can't be modified
pub const E0403: Code = Code(&Entry { code: "E0403", title: "modifying what can't be modified", reference: "modes.what-can-be-modified", rule: "Only `var` bindings and `inout` parameters can be modified. `let` bindings and `let` parameters can't, receivers taken by `self` among them. Neither can the bindings that a pattern makes outside a `var` (patterns.var-bindings). Modifying any of them is E0403, modifying what can't be modified, at the place modified. That error is reported alone: the modification takes no part in the law, so it never also gives E0402 or E0404. A parameter that the callee needs to modify is rebound with `var x = x`.", tier: "core", phase: "analyses", help: "A `let` binding or a parameter never changes. Declare the binding with `var`, or copy the parameter into one, as `var x = x`; a closure can't change what it captures.", span: "The place that is modified.", retired: false, examples: &[Example { wrong: "fn total(prices: List<i64>) -> i64 {\n  let sum = 0\n  for p in prices { sum += p }\n  sum\n}\n", line: 3, right: "fn total(prices: List<i64>) -> i64 {\n  var sum = 0\n  for p in prices { sum += p }\n  sum\n}\n" }] });
/// changing a list while reading it
pub const E0404: Code = Code(&Entry { code: "E0404", title: "changing a list while reading it", reference: "modes.change-while-iterating", rule: "Inside the body of a `for` loop over a place, a modification of an overlapping place is E0404, changing a list while reading it, at the modification. That includes a modification through a call that takes the place `inout`, and through a method with `inout self` on a place that contains it. An example is `cart.remove(id)` inside `for item in cart.items`. A modification that conflicts with several reads, as inside two nested `for` loops over one list, gets one E0404. A loop over a value that isn't a place, such as `xs.enumerate(0)`, iterates that value, so its body may modify `xs`. The error offers two fixes: `retain` (std.list-changes), or collecting the changes during the loop and applying them after it.", tier: "core", phase: "analyses", help: "Changing a list while a `for` loop reads it would silently copy it. Build the changes in another list and apply them after the loop, or loop over its indexes.", span: "The modification: the place assigned, the argument passed `inout`, or the receiver taken by `inout self`.", retired: false, examples: &[Example { wrong: "fn doubled(inout orders: List<i64>) { for o in orders { orders.push(o) } }\n", line: 1, right: "fn doubled(inout orders: List<i64>) { orders = orders.concat(orders) }\n" }] });
/// repeated row element
pub const E0500: Code = Code(&Entry { code: "E0500", title: "repeated row element", reference: "effects.repeated-elements", rule: "A row holds `io` at most once and at most one `raise<E>` label, and a written row holds at most one row variable. A second `io`, a second `raise` label and a second row variable are each E0500, repeated row element, at the repeated element. A row holds each effect once too (handlers.effects-in-rows). The implicit row variables of non-escaping parameters are never written, so a function's own row, and the rows that a body forms, may hold several of them.", tier: "core", phase: "types", help: "A row names each effect once. Delete the repeated one.", span: "The repeated element.", retired: false, examples: &[Example { wrong: "fn log(message: str) / {io, io} { print(message) }\n", line: 1, right: "fn log(message: str) / io { print(message) }\n" }] });
/// effect name as a row variable
pub const E0501: Code = Code(&Entry { code: "E0501", title: "effect name as a row variable", reference: "effects.effect-names", rule: "A row variable can't be named `io`, which in a row is always the label. Nor can it be named `panic` or `alloc`, which are implicit effects and never written (facts.implicit-effects). Each of these names is E0501, effect name as a row variable, where the variable is declared or written. `panic` or `alloc` written as an element of a row is E0501 too.", tier: "core", phase: "items", help: "`panic` and `alloc` are inferred, never written in a row. To forbid one, write `without alloc` after the signature.", span: "The row variable, where it is declared or written.", retired: false, examples: &[Example { wrong: "fn squares(n: i64) -> List<i64> / alloc { [n * n] }\n", line: 1, right: "fn squares(n: i64) -> List<i64> { [n * n] }\n" }] });
/// effect that doesn't fit the row
pub const E0502: Code = Code(&Entry { code: "E0502", title: "effect that doesn't fit the row", reference: "effects.inference", rule: "A body's effects are inferred, and they must fit within its declared row. A call contributes its callee's row as instantiated at the call. That row holds what the arguments given to the callee's non-escaping parameters pass through (effects.non-escaping-parameters). A closure literal contributes nothing where it is written. Its body's effects become part of the closure's type, and fit the closure's own row, apart from the row of the body around it. An effect that doesn't fit a row is E0502, effect that doesn't fit the row, at the first call, `raise` or performance in the body that performs it.", tier: "core", phase: "types", help: "A function's row lists the effects it performs, as `/ io` for printing, so that its callers see them. Add the effect to the row.", span: "The first call or `raise` in the body that performs the effect.", retired: false, examples: &[Example { wrong: "fn log(message: str) { print(message) }\n", line: 1, right: "fn log(message: str) / io { print(message) }\n" }] });
/// two error types
pub const E0503: Code = Code(&Entry { code: "E0503", title: "two error types", reference: "effects.one-error-type", rule: "A body raises at most one error type. A body that raises a type other than the one its row declares is E0503, two error types, at the first `raise` or call that does. A closure's body and the operand of a `try … catch` declare no row. In them, the first `raise` or raising call in evaluation order fixes the error type. A later one that raises another type is E0503. A row gets one E0503, at the first `raise` or call that raises a second error type.", tier: "core", phase: "types", help: "Code raises one error type. Declare one type with a variant for each failure, or convert one error into the other where they meet.", span: "The call or `raise` that raises the second error type.", retired: false, examples: &[Example { wrong: "type ParseError = | Empty\n\nfn parse(text: str) -> i64 / raise<ParseError> {\n  if text == \"\" { raise Empty }\n  raise \"not a number: {text}\"\n}\n", line: 5, right: "type ParseError = | Empty | NotANumber(str)\n\nfn parse(text: str) -> i64 / raise<ParseError> {\n  if text == \"\" { raise Empty }\n  raise NotANumber(text)\n}\n" }] });
/// reason on an arm that isn't a catch-all
pub const E0504: Code = Code(&Entry { code: "E0504", title: "reason on an arm that isn't a catch-all", reference: "effects.reasons-only-on-catch-alls", rule: "`because` on an arm that isn't a catch-all is E0504, reason on an arm that isn't a catch-all, even when the arm names the only variant of the error type. An arm with a guard can't take `because` at all, and the reason is a string literal with no interpolation. The grammar rejects both (E0100).", tier: "core", phase: "types", help: "Only a catch-all arm, `_` or a binding, gives a reason with `because`, saying why dropping every error is right. Delete the reason from this arm.", span: "The reason.", retired: false, examples: &[Example { wrong: "type ParseError = | Empty | NotANumber\n\nfn parse(text: str) -> i64 / raise<ParseError> { raise NotANumber }\n\nfn count(text: str) -> i64 {\n  try parse(text) catch {\n    Empty because \"an empty line counts zero\" => 0\n    NotANumber => 1\n  }\n}\n", line: 7, right: "type ParseError = | Empty | NotANumber\n\nfn parse(text: str) -> i64 / raise<ParseError> { raise NotANumber }\n\nfn count(text: str) -> i64 {\n  try parse(text) catch {\n    Empty => 0\n    NotANumber => 1\n  }\n}\n" }] });
/// raising call without `try`
pub const E0505: Code = Code(&Entry { code: "E0505", title: "raising call without `try`", reference: "effects.marking", rule: "`try e` has the type and the effects of `e`, and changes nothing else: it marks the calls in `e` that can raise. Every call whose callee's row, as instantiated at the call, holds a `raise` label must sit inside the operand of some `try`. The `try` may be outside the closure literal that holds the call, so `try xs.map(|l| parse(l))` marks both `map` and `parse`. The arms of a `catch` are not part of its operand, so a raising call inside an arm needs a `try` of its own. A raising call with no `try` is E0505, raising call without `try`, which offers a fix that inserts one.", tier: "core", phase: "analyses", help: "A call that can raise is marked, so the places where a function can stop are visible: write `try` before it, and `catch` after it to handle the error here.", span: "The call.", retired: false, examples: &[Example { wrong: "type ParseError = | Empty\n\nfn parse(text: str) -> i64 / raise<ParseError> { raise Empty }\n\nfn total(lines: List<str>) -> i64 / raise<ParseError> { parse(lines[0]) }\n", line: 5, right: "type ParseError = | Empty\n\nfn parse(text: str) -> i64 / raise<ParseError> { raise Empty }\n\nfn total(lines: List<str>) -> i64 / raise<ParseError> { try parse(lines[0]) }\n" }] });
/// `catch` around a failure that belongs to the caller
pub const E0506: Code = Code(&Entry { code: "E0506", title: "`catch` around a failure that belongs to the caller", reference: "effects.catch-around-row-variables", rule: "Take a call in the operand of a `catch` whose callee's row, as instantiated at the call, holds a row variable `v` of the enclosing function, written or implicit. The call is E0506, `catch` around a failure that belongs to the caller, at the call, unless that row also holds `raise<E>` and the enclosing signature pairs `v` with `E`. A call through a row that holds several such variables gets one E0506.\nThe rule skips a call inside a closure literal that is itself inside the operand. It also skips a call inside the operand of a nearer `catch` inside it, which that `catch` reports. A `catch` that sits inside a closure literal is checked like any other, its operand being the code between `try` and `catch`. Tests and doc examples have no parameters and declare no row variables, so the rule never applies to their bodies.", tier: "core", phase: "analyses", help: "The failures of a function parameter belong to your caller, unless its type names their error. Write `raise<E>` in the parameter's row to handle them here.", span: "The call.", retired: false, examples: &[Example { wrong: "type ParseError = | Empty\n\nfn parse(text: str) -> i64 / raise<ParseError> { raise Empty }\n\nfn safe(text: str, fallback: fn() -> i64) -> i64 {\n  try {\n    let n = parse(text)\n    n + fallback()\n  }\n    catch _ because \"a failure counts as zero\" => 0\n}\n", line: 8, right: "type ParseError = | Empty\n\nfn parse(text: str) -> i64 / raise<ParseError> { raise Empty }\n\nfn safe(text: str, fallback: fn() -> i64) -> i64 {\n  let n = try parse(text) catch _ because \"a failure counts as zero\" => 0\n  n + fallback()\n}\n" }] });
/// failures passed on without their error type
pub const E0507: Code = Code(&Entry { code: "E0507", title: "failures passed on without their error type", reference: "effects.passing-to-paired-variables", rule: "A use of a function, called or taken as a value, instantiates the row variables of its signature, written and implicit. Suppose the signature pairs a row variable `v` with an error type `E`. Suppose too that the use gives `v` a row that holds a row variable `r` of the enclosing function, written or implicit. Then the enclosing signature must pair `r` with the type that the use gives `E`. Otherwise the use is E0507, failures passed on without their error type, at the use. The rule applies inside closure literals too. So `fn wrap(g: fn() -> i64) -> Result<i64, Box> { Result.of(g) }` is E0507, and with `g: fn() -> i64 / raise<Box>` it is accepted.", tier: "core", phase: "analyses", help: "This would take your caller's failures for an error of its own type. Write `raise<E>` in the parameter's row, so that callers pass only those.", span: "The use of the function: the call, or its name taken as a value.", retired: false, examples: &[Example { wrong: "type Box = { v: i64 }\n\nfn wrap(g: fn() -> i64) -> Result<i64, Box> { Result.of(g) }\n", line: 3, right: "type Box = { v: i64 }\n\nfn wrap(g: fn() -> i64 / raise<Box>) -> Result<i64, Box> { Result.of(g) }\n" }] });
/// function parameter that escapes
pub const E0508: Code = Code(&Entry { code: "E0508", title: "function parameter that escapes", reference: "effects.no-escape", rule: "Each occurrence of a non-escaping parameter in its function's body must be one of these, and so must each closure literal that contains one at any depth:\n- the callee of a call;\n- an argument given to a non-escaping parameter of the function or method that a call names.\nAnything else is E0508, function parameter that escapes. These uses of the parameter are E0508:\n- storing it in a record, a variant, a list, a map or a tuple;\n- returning it;\n- binding it to a local;\n- assigning it;\n- passing it to any other parameter, a function value's included.\nThe error offers a fix that writes `escaping` before the parameter. Each parameter that escapes gets one E0508, at the first occurrence or closure literal in source order that breaks the rule. A row that doesn't hold a parameter's implicit row variable, where the variable meets it, is no error of its own. The variable reaches such a row only through a use that breaks this rule.", tier: "core", phase: "analyses", help: "A function parameter passes its effects through to the caller, so it is only called during the call. Mark it `escaping` to keep it, and its row is then exactly the one written.", span: "The first use that keeps the parameter: the parameter's name, or the closure literal that names it.", retired: false, examples: &[Example { wrong: "type Button = { label: str, on_click: fn() / io }\n\nfn button(label: str, on_click: fn() / io) -> Button { Button { label, on_click } }\n", line: 3, right: "type Button = { label: str, on_click: fn() / io }\n\nfn button(label: str, escaping on_click: fn() / io) -> Button { Button { label, on_click } }\n" }] });
/// row variable on a parameter that passes its effects through
pub const E0509: Code = Code(&Entry { code: "E0509", title: "row variable on a parameter that passes its effects through", reference: "effects.row-variables", rule: "Only functions declare row variables. A lowercase generic of a type or an `impl` block is a syntax error (E0100). A function writes its row variables in its own row, in its result type, and in the types of its parameters that aren't non-escaping (effects.non-escaping-parameters). A row variable written in the type of a non-escaping parameter, at any depth, is E0509, row variable on a parameter that passes its effects through. It is reported at the first row variable written in that type, once for each such parameter, and the parameter's type is then the error type. A lowercase name in a row that the function doesn't declare is an unknown name (E0211).", tier: "core", phase: "items", help: "A function parameter passes the effects its row doesn't name through to the caller, so a row variable adds nothing. Delete it, or mark the parameter `escaping` if the function keeps it.", span: "The first row variable written in the parameter's type.", retired: false, examples: &[Example { wrong: "fn apply<e>(x: i64, f: fn(i64) -> i64 / e) -> i64 / e { f(x) }\n", line: 1, right: "fn apply(x: i64, f: fn(i64) -> i64) -> i64 { f(x) }\n" }] });
/// property that performs `io`
pub const E0510: Code = Code(&Entry { code: "E0510", title: "property that performs `io`", reference: "tests.property-io", rule: "A property performs no `io`. The first call in its body that performs `io` is E0510, property that performs `io`, at the call (effects.inference). So a property's cases, its counterexample and its verdict depend on its text alone (tests.seeds).", tier: "core", phase: "types", help: "A property runs on generated cases and gives the same verdict on every run, so it can't read or write the world. Remove the `print`.", span: "The first call that performs `io`.", retired: false, examples: &[Example { wrong: "/// prop: |a: i64, b: i64| { print(\"{a} {b}\"); add(a, b) == add(b, a) }\nfn add(a: i64, b: i64) -> i64 { a +% b }\n", line: 1, right: "/// prop: |a: i64, b: i64| add(a, b) == add(b, a)\nfn add(a: i64, b: i64) -> i64 { a +% b }\n" }] });
/// handler that doesn't match its effect
pub const E0511: Code = Code(&Entry { code: "E0511", title: "handler that doesn't match its effect", reference: "handlers.handler-literals", rule: "A handler is a value that implements each operation of an effect `Name` once. Its literal is `handler Name { fn op(…) -> T { body } … }`, or `handler Name -> R { … }` for a handler that takes control (handlers.resuming). Each operation has the parameter and result types that the effect declares, with the effect's type arguments substituted, which the literal writes or inference gives. Each of these is E0511, handler that doesn't match its effect:\n- an operation missing, or implemented twice;\n- an operation that the effect doesn't declare;\n- an operation with other types, among them one written with type parameters, a `where` clause or a `without` limit, which no operation of an effect has (syntax.declarations);\n- a handler literal of `async` (tasks.async).\nA handler captures the bindings its bodies name as a closure literal does, by copy when it is made (expressions.capture). Its bodies may perform the effects of their operations' rows, and those of the handler's type (handlers.handler-types). Anything more is E0502 in the body: a raise, or a declared effect, that the operation's row doesn't hold.", tier: "advanced", phase: "types", help: "A handler implements every operation of its effect, with the parameter and result types that the effect declares. Add the missing operations.", span: "The handler's effect, or `async` in an `async` literal.", retired: false, examples: &[Example { wrong: "effect Ask {\n  fn ask() -> i64\n  fn tell(n: i64)\n}\n\nfn answer() -> i64 {\n  with (handler Ask { fn ask() -> i64 { 1 } }) { Ask.ask() }\n}\n", line: 7, right: "effect Ask {\n  fn ask() -> i64\n  fn tell(n: i64)\n}\n\nfn answer() -> i64 {\n  let h = handler Ask {\n    fn ask() -> i64 { 1 }\n    fn tell(n: i64) {}\n  }\n  with h { Ask.ask() }\n}\n" }] });
/// effect that reaches `main`
pub const E0512: Code = Code(&Entry { code: "E0512", title: "effect that reaches `main`", reference: "handlers.no-effect-reaches-main", rule: "The row of `main` holds no user-defined effect (program.main), and neither does a test's body or a doc example's (program.test-declarations). So every performance in a program runs under a handler. A row of `main` that holds one is E0512, effect that reaches `main`, at the effect in the row. So is the first performance that a test, a doc example or `main` makes outside every `with` of its effect, in place of the E0502 that handlers.performing-operation would give.", tier: "advanced", phase: "types", help: "A user-defined effect is handled before `main`, a test or an example ends. Wrap the code in `with (handler …) { … }`.", span: "The effect in the row, or the first performance outside every `with` of its effect.", retired: false, examples: &[Example { wrong: "effect Log {\n  fn log(msg: str)\n}\n\nfn main() / io {\n  Log.log(\"start\")\n}\n", line: 6, right: "effect Log {\n  fn log(msg: str)\n}\n\nfn main() / io {\n  with (handler Log { fn log(msg: str) { print(msg) } }) { Log.log(\"start\") }\n}\n" }] });
/// `resume` outside a handler's operation
pub const E0513: Code = Code(&Entry { code: "E0513", title: "`resume` outside a handler's operation", reference: "handlers.resume-outside-operation", rule: "`resume` anywhere but in the body of an operation of a handler written with `-> R` is E0513, `resume` outside a handler's operation. This holds in a handler nested in that body too.", tier: "advanced", phase: "types", help: "`resume` stands only in an operation of a handler written `handler Name -> R`, which takes control. An operation of any other handler gives its value, which resumes the code.", span: "The `resume`.", retired: false, examples: &[Example { wrong: "effect Ask {\n  fn ask() -> i64\n}\n\nfn answer() -> i64 {\n  let h = handler Ask { fn ask() -> i64 { resume(1) } }\n  with h { Ask.ask() }\n}\n", line: 6, right: "effect Ask {\n  fn ask() -> i64\n}\n\nfn answer() -> i64 {\n  let h = handler Ask { fn ask() -> i64 { 1 } }\n  with h { Ask.ask() }\n}\n" }] });
/// operation that may resume twice
pub const E0514: Code = Code(&Entry { code: "E0514", title: "operation that may resume twice", reference: "handlers.resume-at-most-once", rule: "A body resumes at most once on each path. A `resume` is E0514, operation that may resume twice, in each of these places:\n- in a loop;\n- in a closure literal;\n- after another `resume` in sequence;\n- in a branch that runs after another that resumed.\nNo closure holds a `resume`, so a performance, the body that takes it and its `resume` run in one task (tasks.continuations-stay-in-task).", tier: "advanced", phase: "analyses", help: "A handler resumes at most once on every path. Resume once, and combine the values after.", span: "The `resume` that could run a second time.", retired: false, examples: &[Example { wrong: "effect Ask {\n  fn ask() -> i64\n}\n\nfn answer() -> i64 {\n  let h = handler Ask -> i64 {\n    fn ask() -> i64 {\n      let a = resume(1)\n      a + resume(2)\n    }\n  }\n  with h { Ask.ask() }\n}\n", line: 9, right: "effect Ask {\n  fn ask() -> i64\n}\n\nfn answer() -> i64 {\n  let h = handler Ask -> i64 {\n    fn ask() -> i64 {\n      let a = resume(1)\n      a + 2\n    }\n  }\n  with h { Ask.ask() }\n}\n" }] });
/// effect given twice in a row
pub const E0515: Code = Code(&Entry { code: "E0515", title: "effect given twice in a row", reference: "handlers.effects-in-rows", rule: "A row element may be an effect, `Name` or `Name<T…>`, beside `io`, `raise<E>` and a row variable, as in `/ {io, Prices}`. An `Upper` name in a row that names no effect is an unknown name (E0211). A row holds at most one instance of an effect, so `/ {State<i64>, State<str>}` is E0515, effect given twice in a row, at the second instance. An effect performed with other type arguments than the row's is E0311 where it is performed. A function type's row holds effects as any row does, so `fn(str) -> f64 / Prices` is the type of a function value that performs `Prices`.", tier: "advanced", phase: "types", help: "A row holds one instance of each effect. Use one, or declare two effects.", span: "The second instance.", retired: false, examples: &[Example { wrong: "effect State<S> {\n  fn get() -> S\n}\n\nfn count() -> i64 / {State<i64>, State<str>} {\n  State.get()\n}\n", line: 5, right: "effect State<S> {\n  fn get() -> S\n}\n\nfn count() -> i64 / State<i64> {\n  State.get()\n}\n" }] });
/// handler around an effect that belongs to the caller
pub const E0516: Code = Code(&Entry { code: "E0516", title: "handler around an effect that belongs to the caller", reference: "handlers.with-pairing", rule: "A `with` handles every performance of its effect that reaches it, as a `catch` handles every raise (effects.innermost-catch). Take a call in a `with`'s block whose callee's row, as instantiated at the call, holds a row variable `v` of the enclosing function. The call is E0516, handler around an effect that belongs to the caller, unless the row also holds the effect and the enclosing signature pairs `v` with it. The error is at the call. The rule has the exceptions that effects.catch-around-row-variables gives a `catch`'s operand. A signature pairs a row variable with each effect that a row of it holds beside the variable. effects.passing-to-paired-variables and effects.what-paired-variable-may-raise apply to effects as to error types.", tier: "advanced", phase: "analyses", help: "A call of a function parameter performs your caller's effects, which this `with` would capture. Name the effect in the parameter's row to handle it here.", span: "The call.", retired: false, examples: &[Example { wrong: "effect Ask {\n  fn ask() -> i64\n}\n\nfn run(f: fn() -> i64) -> i64 {\n  with (handler Ask { fn ask() -> i64 { 1 } }) { f() }\n}\n", line: 6, right: "effect Ask {\n  fn ask() -> i64\n}\n\nfn run(f: fn() -> i64 / Ask) -> i64 {\n  with (handler Ask { fn ask() -> i64 { 1 } }) { f() }\n}\n" }] });
/// operation with an `inout` parameter
pub const E0517: Code = Code(&Entry { code: "E0517", title: "operation with an `inout` parameter", reference: "handlers.no-inout-parameter", rule: "An operation's parameter is never `inout`. A parameter marked `inout` in the effect's declaration is E0517, operation with an `inout` parameter, at the parameter's name. So is one that a handler's operation marks `inout`, in place of the E0511 that its mismatch with the effect would give. An operation that changes a value takes it and returns the new one, as `fn bump(n: i64) -> i64` does. The code that performs it assigns the result: `x = Bump.bump(x)`.", tier: "advanced", phase: "items", help: "An operation takes values, not places. Take the value and return the new one, which the code that performs it assigns.", span: "The parameter's name.", retired: false, examples: &[Example { wrong: "effect Counter {\n  fn bump(inout n: i64)\n}\n", line: 2, right: "effect Counter {\n  fn bump(n: i64) -> i64\n}\n" }] });
/// effect with no operations
pub const E0518: Code = Code(&Entry { code: "E0518", title: "effect with no operations", reference: "handlers.declaring-effect", rule: "`effect Name { fn op(…) -> T … }` declares an effect in the type namespace (declarations.namespaces) (the `effect` and `operation` productions, syntax.declarations). An effect takes type parameters as a type does, as in `effect State<S> { … }`. An effect has one or more operations, and an effect with none is E0518, effect with no operations, at its name. Each operation is a function head with a name used once in the effect (E0208), parameters, a result, and a row of its own. A handler's implementation of the operation may perform that row, and the operation then performs it where it is performed. The `with` that installs the handler performs that row's effects too, since the body performs them on the handlers outside the `with` (handlers.with). An operation has no generics, no `self`, no `inout` parameter (handlers.no-inout-parameter), no `inout` result and no body. An effect may be `pub` and take doc comments, as a type does, and the operations of a `pub` effect are its API (versions.api). Effects belong to the advanced tier (handlers.advanced-tier).", tier: "advanced", phase: "items", help: "An effect is its operations, so one with none can never be performed. Declare its operations.", span: "The effect's name.", retired: false, examples: &[Example { wrong: "effect Audited {\n}\n", line: 1, right: "effect Audited {\n  fn audit(note: str)\n}\n" }] });
/// malformed manifest
pub const E0600: Code = Code(&Entry { code: "E0600", title: "malformed manifest", reference: "packages.manifest", rule: "A package's manifest, `stilt.toml`, is a TOML 1.0 document with at most two tables, `[package]` and `[dependencies]`. A file that isn't TOML 1.0 is E0600, malformed manifest. So is any other table or key, and a value of a type or a form other than this chapter gives. An empty file is a manifest with no name and no dependencies.", tier: "core", phase: "items", help: "stilt.toml holds a `[package]` table with `name` and `edition`, and `link` for C libraries, and a `[dependencies]` table whose entries give `path`, or `from`, `version` and `hash`, and `may`. Fix the line it points at.", span: "The key or the value it is about: the unknown key or table's name, the value of the wrong type or form, the entry's key for a combination of keys that isn't allowed; for a file that isn't TOML 1.0, the first character from which no TOML document can continue.", retired: false, examples: &[] });
/// dependency that can't be fetched
pub const E0601: Code = Code(&Entry { code: "E0601", title: "dependency that can't be fetched", reference: "packages.fetch-failures", rule: "A dependency that can't be had is E0601, dependency that can't be fetched. It is one of these:\n- a `path` that names no directory holding a `stilt.toml`;\n- a repository that can't be reached or has no version;\n- a version that a repository doesn't have, or sends past the limits of packages.fetching or not well formed;\n- a version whose tree holds no `stilt.toml` at its root;\n- a fetched package whose manifest has a `path` entry, or a `from` entry without its `version` or `hash`, which can't be built from its content.\nE0601 is at the entry's key in the manifest that holds it. For a fetched package that can't be built from its content, it is at the first entry of the root's manifest through which the package arrives.", tier: "core", phase: "items", help: "A dependency comes from a directory that holds its stilt.toml, with `path`, or from a git repository, with `from`, whose versions are tags such as `v1.2.0`.", span: "The entry's key, in the manifest that holds it; for a fetched package that can't be built from its content, the first entry of the root's manifest through which it arrives.", retired: false, examples: &[] });
/// content that doesn't match its hash
pub const E0602: Code = Code(&Entry { code: "E0602", title: "content that doesn't match its hash", reference: "packages.checked-content", rule: "A command computes a package's content hash each time it reads the package, from the cache or from the network. Content whose hash isn't the one that a manifest gives it is E0602, content that doesn't match its hash, and nothing is built from it. Two hashes that two manifests give one version are E0602 too (versions.selection). E0602 is at the `hash` value that the content doesn't match, when the root's manifest or a path dependency's gives it. Otherwise it is at the first entry of the root's manifest through which the package arrives.", tier: "core", phase: "items", help: "A dependency is pinned by its content's hash, so a changed release is caught, and nothing was built from it. If its author retagged the version on purpose, remove `hash`, and the next `stilt check` pins the new content.", span: "The `hash` value that the content doesn't match, when the root's manifest or a path dependency's gives it; otherwise, and for two hashes of one version, the first entry of the root's manifest through which the package arrives.", retired: false, examples: &[] });
/// dependency named unlike its package
pub const E0603: Code = Code(&Entry { code: "E0603", title: "dependency named unlike its package", reference: "packages.dependency-names", rule: "An entry's key is the dependency's name, which must be the name that the dependency's own manifest gives it. An entry named otherwise is E0603, dependency named unlike its package, at the entry's key. So is a dependency whose manifest gives no name. A package therefore has one name wherever it is used.", tier: "core", phase: "items", help: "A dependency's entry has its package's own name, so that its modules have one name everywhere. Rename the entry.", span: "The entry's key.", retired: false, examples: &[] });
/// version that understates its API change
pub const E0604: Code = Code(&Entry { code: "E0604", title: "version that understates its API change", reference: "versions.checked-versions", rule: "Before a version of a repository is written into a manifest (packages.filling-in), its number is checked against the change in the API since the repository's previous version. The previous version is the repository's highest lower version that has no error. The number must change at least as versions.change-needed asks. A version that changes less is E0604, version that understates its API change, at the entry's key, and isn't written. The error names the first change that needs more, by its address (edits.paths), and offers the repository's highest version that passes. A repository's first version without errors needs no check.\nA version that has an error, checked as a program of its own (packages.dependencies-with-errors), is never written. It is E0607, and the error offers the repository's highest version that has no error and passes.", tier: "core", phase: "items", help: "A release that removes or changes what other packages use needs a new major version, and one that only adds needs a new minor one. Nothing was written to stilt.toml.", span: "The entry's key.", retired: false, examples: &[] });
/// versions that don't agree
pub const E0605: Code = Code(&Entry { code: "E0605", title: "versions that don't agree", reference: "versions.compatible-selections", rule: "The versions that the manifests ask of one repository must have one major number. If a manifest asks for version A of a repository and version B is selected, the API's change from A to B must need no new major version (versions.change-needed). Otherwise the program has E0605, versions that don't agree, which names the first change that needs one, by its address. E0605, and E0602 for two hashes of one version, are reported at the first entry of the root's manifest through which the requests they are about arrive.", tier: "core", phase: "items", help: "A program holds one version of each package, the highest that any manifest asks for, and that version removes what another manifest needs. Ask for a version that keeps it, or change the code that needs it.", span: "The first entry of the root's manifest through which the requests arrive.", retired: false, examples: &[] });
/// two packages with one name
pub const E0606: Code = Code(&Entry { code: "E0606", title: "two packages with one name", reference: "packages.one-name-one-package", rule: "Two packages of one name in a program are E0606, two packages with one name. They may come from two repositories, from a repository and a directory, or from two directories. E0606 is at the first entry of the root's manifest that, with the entries before it, brings both.", tier: "core", phase: "items", help: "A package's modules are named after it, so a program can't hold two packages of one name. Remove one of them.", span: "The first entry of the root's manifest that, with the entries before it, brings both packages.", retired: false, examples: &[] });
/// dependency with errors
pub const E0607: Code = Code(&Entry { code: "E0607", title: "dependency with errors", reference: "packages.dependencies-with-errors", rule: "A path dependency is checked as part of the program. Its files are among the program's own, its diagnostics are reported in them, at paths relative to the root directory, and its parts take edits (edits.parts).\nA fetched dependency is checked with the program too, against the versions that the program selects (versions.selection). Its diagnostics, those of its code and of its manifest, aren't reported. Each fetched dependency that has an error gives the program one E0607, dependency with errors, at the first entry of the root's manifest through which it arrives. None of its warnings is reported. Wherever the program uses an item of a dependency whose declaration has an error, the item has the error type.", tier: "core", phase: "items", help: "A fetched dependency with errors can't be used where they are. Use another version, or tell its author; `stilt show` with the error's code explains it.", span: "The first entry of the root's manifest through which the dependency arrives.", retired: false, examples: &[] });
/// effect that the manifest doesn't grant
pub const E0608: Code = Code(&Entry { code: "E0608", title: "effect that the manifest doesn't grant", reference: "packages.ungranted-effects", rule: "A dependency whose own code performs an effect that its entry doesn't grant is E0608, effect that the manifest doesn't grant, at its entry, once for each effect. So is a dependency whose own code has a capability that its entry doesn't grant (facts.ungranted-capabilities), or holds an `unsafe` block without the grant (c.granting-unsafe).\nThe error names the first function that performs the effect by its address (edits.paths), with the call that performs it, and offers the narrowest grant. That function is the first in the order of the dependency's modules' paths, and then of its source. This holds for the entries of the root's manifest and of its path dependencies' manifests, in their own files. A fetched package's manifest is checked as part of that package (packages.dependencies-with-errors).", tier: "core", phase: "items", help: "A dependency performs only the effects and capabilities that its entry grants with `may`, as `may = [\"fs\"]`, and `unsafe` code only with `unsafe`. Grant what it needs, if you trust it with that.", span: "The entry's key, in the manifest that holds it.", retired: false, examples: &[] });
/// dependency cycle
pub const E0609: Code = Code(&Entry { code: "E0609", title: "dependency cycle", reference: "packages.dependency-cycles", rule: "A package that depends on itself is E0609, dependency cycle. The cycle runs through its own manifest or through those of the packages it names, at the versions selected. E0609 is at the first entry of the root's manifest through which a package of the cycle arrives.", tier: "core", phase: "items", help: "A package can't depend on itself, even through others. Move what both packages use into a package of its own.", span: "The first entry of the root's manifest through which a package of the cycle arrives.", retired: false, examples: &[] });
/// malformed profile
pub const E0610: Code = Code(&Entry { code: "E0610", title: "malformed profile", reference: "builds.profile-form", rule: "A profile is text, one line for each count that isn't 0, `ADDRESS HASH KIND LINE:COL [CALLEE] COUNT`. The lines are sorted by address, hash, place, kind and callee, so that a change of the profile reads as a diff. The fields are these:\n- `ADDRESS` is the body's address and `HASH` its hash (edits.body-addresses, edits.hash);\n- `KIND` is `entry`, `arm`, `loop` or `call`;\n- `LINE:COL` is the place of what the line counts. Its line is counted from the body's first line, that of its declaration, so an edit above the body moves none of its lines. A body's entry is at its `{`. An arm of an `if` is at its condition, or at its pattern for `if let`. Its `else` is at what follows `else`, or at the `if` when it has none. An arm of a `match` or a `catch` is at its pattern, a loop at its keyword, and a call at the call;\n- `CALLEE` is the address of the function that a `call` reaches;\n- `COUNT` is the count rounded down to a power of two.\nMerging adds counts and rounds the sum down again. A line that isn't of this form is E0610, malformed profile, at the line, including a blank line and a line whose count isn't a power of two. `check` reports it, and a profiled run and a release build refuse the program.", tier: "core", phase: "items", help: "A release build reads a profile whole or not at all. Fix the line, or delete the profile and write it again with `stilt run --profile`.", span: "The line, from its first character to its last.", retired: false, examples: &[] });
/// C library that isn't found
pub const E0611: Code = Code(&Entry { code: "E0611", title: "C library that isn't found", reference: "c.finding-libraries", rule: "Every command that checks a program looks for each library of each of its packages as the system's dynamic loader finds one, by the bare name: `libz.dylib` on macOS and `libz.so` elsewhere. It looks without loading the library, so no code of it runs until the program does. A library that isn't found is E0611, C library that isn't found, at its string.", tier: "systems", phase: "items", help: "The system's loader finds each library of `link` as `libNAME.dylib` on macOS and `libNAME.so` on Linux. Install the library, or check its name: `link = [\"z\"]` names zlib.", span: "The library's string in `link`.", retired: false, examples: &[] });
/// C libraries for another target
pub const E0612: Code = Code(&Entry { code: "E0612", title: "C libraries for another target", reference: "c.build-targets", rule: "A program whose packages link a library builds only for the host's own target, the one that `stilt build` writes without `--target`. It builds only when that target's executables load shared libraries, as aarch64 macOS's do. A Linux executable, x86-64 or aarch64, is static, and a WebAssembly module loads no library. A build for any other target is E0612, C libraries for another target, at the first library in the order of c.loading-libraries. A program whose packages link no library may call a function of the target's C library on any target, such as `strlen`, which the build takes from that library. That C library is musl's for x86-64 Linux, and WASI's for `wasm32-wasip1`.", tier: "systems", phase: "items", help: "A program that links C libraries builds only for the machine it is built on. Build it without `--target`, or run it with `stilt run`.", span: "The first library of the program's packages in `link`: the root's first, then each dependency's.", retired: false, examples: &[] });
/// malformed edit
pub const E0700: Code = Code(&Entry { code: "E0700", title: "malformed edit", reference: "edits.refusals", rule: "An edit is refused, with one of these codes, when it:\n| Code | Refusal |\n| --- | --- |\n| E0700, malformed edit | is malformed: its address isn't a path of edits.paths, with `/body` or without it, then `#` and four lowercase hexadecimal digits; or it is a second edit that reads standard input |\n| E0701, address that names no part | names no part of the program's own files: nothing has its path, the declaration has no body, or the part lies in `std` or in a fetched dependency (packages.dependencies-with-errors) |\n| E0702, ambiguous address | names two parts (edits.one-part-per-path) |\n| E0703, stale address | carries a hash other than the part's current hash, since the part has changed since its author read it |\n| E0704, edit that doesn't parse as its part | has a text that doesn't parse as the part (edits.new-text) |\n| E0705, overlapping edits | overlaps another edit: both address one part, or one addresses a declaration and the other its body |\nThe registry checks refusals under `refusal` (errors.registry-phases), before the program. Each comes with no diagnostic of the program, which none of them changes.", tier: "core", phase: "refusal", help: "An edit's address is a path, with `/body` for a body, then `#` and the part's four-digit hash, as `stilt show --json` gives it. Nothing was written.", span: "The part of the address that is malformed, in the command line; the second `-` of an edit that reads standard input again.", retired: false, examples: &[] });
/// address that names no part
pub const E0701: Code = Code(&Entry { code: "E0701", title: "address that names no part", reference: "edits.refusals", rule: "An edit is refused, with one of these codes, when it:\n| Code | Refusal |\n| --- | --- |\n| E0700, malformed edit | is malformed: its address isn't a path of edits.paths, with `/body` or without it, then `#` and four lowercase hexadecimal digits; or it is a second edit that reads standard input |\n| E0701, address that names no part | names no part of the program's own files: nothing has its path, the declaration has no body, or the part lies in `std` or in a fetched dependency (packages.dependencies-with-errors) |\n| E0702, ambiguous address | names two parts (edits.one-part-per-path) |\n| E0703, stale address | carries a hash other than the part's current hash, since the part has changed since its author read it |\n| E0704, edit that doesn't parse as its part | has a text that doesn't parse as the part (edits.new-text) |\n| E0705, overlapping edits | overlaps another edit: both address one part, or one addresses a declaration and the other its body |\nThe registry checks refusals under `refusal` (errors.registry-phases), before the program. Each comes with no diagnostic of the program, which none of them changes.", tier: "core", phase: "refusal", help: "An edit replaces a declaration or a body in the program's own files. Find the path with `stilt show`. Nothing was written.", span: "The path of the address, in the command line.", retired: false, examples: &[] });
