pub const E0705: Code = Code(&Entry { code: "E0705", title: "overlapping edits", reference: "edits.refusals", rule: "An edit is refused, with one of these codes, when it:\n| Code | Refusal |\n| --- | --- |\n| E0700, malformed edit | is malformed: its address isn't a path of edits.paths, with `/body` or without it, then `#` and four lowercase hexadecimal digits; or it is a second edit that reads standard input |\n| E0701, address that names no part | names no part of the program's own files: nothing has its path, the declaration has no body, or the part lies in `std` or in a fetched dependency (packages.dependencies-with-errors) |\n| E0702, ambiguous address | names two parts (edits.one-part-per-path) |\n| E0703, stale address | carries a hash other than the part's current hash, since the part has changed since its author read it |\n| E0704, edit that doesn't parse as its part | has a text that doesn't parse as the part (edits.new-text) |\n| E0705, overlapping edits | overlaps another edit: both address one part, or one addresses a declaration and the other its body |\nThe registry checks refusals under `refusal` (errors.registry-phases), before the program. Each comes with no diagnostic of the program, which none of them changes.", tier: "core", phase: "refusal", help: "Two edits can't change the same code. Make them one edit. Nothing was written.", span: "The address of the later of the two edits, in the command line.", retired: false, examples: &[] });
/// commented-out code
pub const W0001: Code = Code(&Entry { code: "W0001", title: "commented-out code", reference: "lexical.commented-out-code", rule: "A `//` comment whose text, after the `//`, parses as one or more complete statements or items gets the warning W0001, commented-out code, at the comment. Statements include expression statements (expressions.statements). Doc comments and annotations are not `//` comments in this sense. So `// print(\"debug: {total}\")`, `// pub fn f() {}`, `// var n = 0`, `// f(x)` and `// i.e. done` get the warning. `// see f(x)` and `// TODO(ana): tidy up` don't parse, and get none.", tier: "core", phase: "warnings", help: "Commented-out code goes stale while readers take it as true. Delete it; version control keeps it.", span: "The comment.", retired: false, examples: &[Example { wrong: "fn total(prices: List<i64>) -> i64 {\n  // let discount = 10\n  prices.fold(0, |sum, p| sum + p)\n}\n", line: 2, right: "fn total(prices: List<i64>) -> i64 {\n  prices.fold(0, |sum, p| sum + p)\n}\n" }] });
/// stale doc
pub const W0002: Code = Code(&Entry { code: "W0002", title: "stale doc", reference: "docs.stale", rule: "A doc is stale when its pin's signature hash isn't its signature's hash now, while its pin's doc hash is its doc's hash now. `check` and `test` report each stale doc as W0002, stale doc, at the doc's first line. W0002 is a warning outside bodies, reported whenever the program has no syntax error, in a declaration with errors too (errors.phases).\nA doc without a pin is never stale. Neither is a doc whose hash isn't its pin's, whatever its signature. W0002's fix pins again a doc that is still right: an edit of the declaration through `check --edit` (edits.fixes-as-edits), which sends it back as it is.", tier: "core", phase: "warnings", help: "The doc was written for the old signature. Update it, or, if it still holds, send the declaration back as it is, which pins it again.", span: "The first line of the doc.", retired: false, examples: &[] });
/// hole
pub const W0300: Code = Code(&Entry { code: "W0300", title: "hole", reference: "declarations.typed-holes", rule: "`?` is a typed hole, or hole: an expression that stands for code not yet written. It may be a whole body, `= ?`, or stand inside one, as in `a + ?`. A hole takes the type its context expects. A hole whose type can't be inferred, as in `let x = ?`, is E0312, type that can't be inferred (types.known-types). Each hole is the warning W0300, hole, at the hole. `?` is always a hole, even directly before `.`, `..` or `..=` (types.hole-before-dot). It is never an operator, so `parse(s)?` is E0100, syntax error.", tier: "core", phase: "warnings", help: "A hole `?` stands for code not written yet: the program checks and runs, and panics if it reaches the hole.", span: "The hole.", retired: false, examples: &[Example { wrong: "fn shipping(weight: i64) -> i64 { ? }\n", line: 1, right: "fn shipping(weight: i64) -> i64 { 5 + weight / 1000 }\n" }] });
/// unreachable arm
pub const W0301: Code = Code(&Entry { code: "W0301", title: "unreachable arm", reference: "patterns.unreachable-arms", rule: "An arm that can never match is an unreachable arm, the warning W0301, at its pattern. An arm can never match when its pattern, with each constant in it read as `_`, matches no value that the earlier arms without guards or constants leave. An arm that holds a pattern on a part of the value whose type is the error type is never reported, and makes no later arm unreachable.", tier: "core", phase: "warnings", help: "An earlier arm already matches every value that this one matches, so it never runs. Move it before that arm, or delete it.", span: "The arm's pattern.", retired: false, examples: &[Example { wrong: "fn label(n: i64) -> str {\n  match n {\n    _ => \"any\"\n    0 => \"zero\"\n  }\n}\n", line: 4, right: "fn label(n: i64) -> str {\n  match n {\n    0 => \"zero\"\n    _ => \"any\"\n  }\n}\n" }] });
/// duplicate body
pub const W0302: Code = Code(&Entry { code: "W0302", title: "duplicate body", reference: "docs.duplicate-bodies", rule: "Of the bodies that are the same, the first is the one that comes first in the program. It is in the file whose path sorts first by bytes, then at the first position in it. The later ones are those at which an error of several places is reported (errors.several-places). Each later one is W0302, duplicate body, at its function's name, naming the first by its path (edits.paths). It is a warning of phase 3 of the later body, and neither body has an error (docs.bodies-compared). Three copies give two W0302, each naming the first.", tier: "core", phase: "warnings", help: "Two copies of one body drift apart when only one is fixed. Call the first function, or move what both do into a function that each calls.", span: "The name of the later function, in the file whose path sorts last, then at its last position.", retired: false, examples: &[Example { wrong: "type Order = { qty: i64, grams: i64, box: i64 }\n\nfn mass(o: Order) -> i64 { o.qty * o.grams + o.box * 2 + o.qty - 1 }\n\nfn heft(p: Order) -> i64 { p.qty * p.grams + p.box * 2 + p.qty - 1 }\n\nfn main() / io {\n  let o = Order { qty: 2, grams: 300, box: 50 }\n  print(\"{mass(o)} {heft(o)}\")\n}\n", line: 5, right: "type Order = { qty: i64, grams: i64, box: i64 }\n\nfn mass(o: Order) -> i64 { o.qty * o.grams + o.box * 2 + o.qty - 1 }\n\nfn main() / io {\n  let o = Order { qty: 2, grams: 300, box: 50 }\n  print(\"{mass(o)} {mass(o)}\")\n}\n" }] });
/// `if let` that always matches
pub const W0303: Code = Code(&Entry { code: "W0303", title: "`if let` that always matches", reference: "expressions.if-let-always", rule: "An `if let` whose pattern matches every value of the type of `e`, as patterns.algorithm decides it for a `match` of that one arm, always runs its first block: its `else` never runs, and a `let` says the same. It gets the warning W0303, `if let` that always matches, at its pattern, unless the pattern holds a constant (patterns.guards-and-constants) or `e` has the error type (errors.error-type). So `if let x = xs.first() { … }` gets it, binding the `Option` itself, where `if let Some(x) = xs.first() { … }` binds what it holds.", tier: "core", phase: "warnings", help: "The pattern matches every value, so the first block always runs with the whole value bound. To match what an `Option` holds, write `if let Some(x) = …`; to bind the value, write `let`.", span: "The pattern.", retired: false, examples: &[Example { wrong: "fn first_or_zero(xs: List<i64>) -> i64 {\n  if let x = xs.first() { x else 0 } else { 0 }\n}\n", line: 2, right: "fn first_or_zero(xs: List<i64>) -> i64 {\n  if let Some(x) = xs.first() { x } else { 0 }\n}\n" }] });
/// `try` with nothing to mark
pub const W0500: Code = Code(&Entry { code: "W0500", title: "`try` with nothing to mark", reference: "effects.empty-try", rule: "A `try` without `catch` whose operand contains no raising call is W0500, `try` with nothing to mark. So is a `try … catch` whose operand raises nothing, so that its error type is `Never` (effects.catch). The arms of such a `catch` never run, and get neither W0301 (patterns.unreachable-arms) nor W0501 (effects.catch-alls-need-reason).", tier: "core", phase: "warnings", help: "`try` marks calls that can raise, and nothing here can. Delete it.", span: "The `try`.", retired: false, examples: &[Example { wrong: "fn double(n: i64) -> i64 { try n * 2 }\n", line: 1, right: "fn double(n: i64) -> i64 { n * 2 }\n" }] });
/// catch-all without a reason
pub const W0501: Code = Code(&Entry { code: "W0501", title: "catch-all without a reason", reference: "effects.catch-alls-need-reason", rule: "An arm without a guard whose pattern is `_` or a variable is a catch-all. A catch-all needs nothing more in either of these cases:\n- it raises: its body is a `raise`, or a block whose final expression is one;\n- its pattern is a variable that its body uses, inside a closure or an interpolation too, but not through a later binding that shadows it.\nSo `catch e => return Err(Bad(e))` needs no reason. Any other catch-all gives a reason, with `because` and a string literal between its pattern and `=>`, in either form of `catch`. An example is `catch _ because \"old configs omit the port\" => 8080`. A catch-all with neither a raise, a use of its error nor a reason is W0501, catch-all without a reason. A catch-all that can never match gets only W0301 instead (patterns.unreachable-arms).", tier: "core", phase: "warnings", help: "An arm that drops every error hides failures. Raise the error again, use it, or say why dropping it is right, as `catch _ because \"…\" => …`.", span: "The arm's pattern.", retired: false, examples: &[Example { wrong: "type ParseError = | Empty\n\nfn parse(text: str) -> i64 / raise<ParseError> { raise Empty }\n\nfn count(text: str) -> i64 { try parse(text) catch _ => 0 }\n", line: 5, right: "type ParseError = | Empty\n\nfn parse(text: str) -> i64 / raise<ParseError> { raise Empty }\n\nfn count(text: str) -> i64 { try parse(text) catch _ because \"an empty line counts zero\" => 0 }\n" }] });
/// not a viewable type
pub const E0420: Code = Code(&Entry { code: "E0420", title: "not a viewable type", reference: "views.viewable-types", rule: "The viewable types are `str` and `List<U>`. A `View<T>` requires `T` viewable, and any other `T` is E0420, not a viewable type, where the type is written or inferred.", tier: "advanced", phase: "analyses", help: "Only a `str` or a `List` can be viewed. Take the value itself.", span: "The type argument of `View` or `Iter.of`'s argument, where it is written or inferred.", retired: false, examples: &[Example { wrong: "use std.view\n\nfn count(v: view.View<i64>) -> i64 { v.len() }\n", line: 3, right: "use std.view\n\nfn count(v: view.View<List<i64>>) -> i64 { v.len() }\n" }] });
/// a view can't be stored
pub const E0421: Code = Code(&Entry { code: "E0421", title: "a view can't be stored", reference: "views.view-types", rule: "The view types are `View<T>`, `Iter<T>`, a closure type whose literal captures a value of a view type (views.fixed), and `Option<V>` for a view type `V`. A view type may be the type of a local binding, a parameter, a function's result, a closure's capture, and a type argument of a generic function's call. Anywhere else, it is E0421, a view can't be stored, at the type. Such places include these:\n- a field of a record;\n- a variant's payload other than `Option`'s;\n- an element of a `List` or a `Map`;\n- a component of a tuple;\n- a type argument of a declared type.\nA generic function instantiated with a view type keeps this rule: `[v]` for a view `v` is E0421, through `List<T>`.", tier: "advanced", phase: "analyses", help: "A view reads a value that someone else holds, so it can't be stored where it could outlive it. Store the value, or the range it covers.", span: "The view type where it is written in a field, a payload, an element, a component or a type argument of a declared type, or the expression that builds such a value from a view.", retired: false, examples: &[Example { wrong: "use std.view\n\ntype Line = { text: view.View<str> }\n", line: 3, right: "type Line = { text: str }\n" }] });
/// a view outlives its source
pub const E0422: Code = Code(&Entry { code: "E0422", title: "a view outlives its source", reference: "views.escaping", rule: "A view never leaves the scope that binds one of its sources. So none of these reaches outside:\n- a block whose value views a binding the block makes;\n- the arm of a `match` or an `if let` whose value views a binding of its pattern;\n- a `when` whose value views a name it holds, which stands for the place of a value the `when` releases when its block ends (shared.when);\n- the value of a `for` body.\nA view escapes a function (modes.escaping) only into its result, and only when every one of its sources is a parameter that views.across-calls allows. Any other escape is E0422, a view outlives its source, at the expression that escapes, naming the source. Among such escapes are these:\n- a block's value that views the block's own binding;\n- an assignment of a view to a variable bound outside the scope of one of its sources;\n- returning a view of a local;\n- capturing a view in a closure that escapes.\nA view of an `inout` parameter in a result is the error of projections.results-that-write unless the result writes it.", tier: "advanced", phase: "analyses", help: "The view reads a local that is gone when the function returns. Return a value of its own, or view a parameter instead.", span: "The expression that makes the view escape: the value returned, or the closure literal that captures it.", retired: false, examples: &[Example { wrong: "use std.view\n\nfn rest(xs: List<i64>) -> view.View<List<i64>> {\n  let ys = xs.slice(1, xs.len())\n  let v = view.View.all(ys)\n  v\n}\n", line: 6, right: "fn rest(xs: List<i64>) -> List<i64> {\n  xs.slice(1, xs.len())\n}\n" }] });
/// changing a value while a view reads it
pub const E0423: Code = Code(&Entry { code: "E0423", title: "changing a value while a view reads it", reference: "views.change-while-viewed", rule: "While a view of a source lives, a modification of a place that overlaps the source is E0423, changing a value while a view reads it, at the modification. This is the law of exclusivity, applied to the view's read. It includes a later operand of the expression that makes the view, or of a call that a view is passed to, which changes a source that an earlier operand gives (views.reads-that-last). So with `fn bump(inout xs: List<i64>) -> i64`, the argument `inout xs` is E0423 in `View.of(xs, bump(inout xs), 2)`, in `View.of(xs, 0, bump(inout xs))` and in `f(View.all(xs), bump(inout xs))`. The error names the view and the line where its read ends. It is counted as E0404 is (modes.change-while-iterating). The error offers two fixes: make the change before the view, or end the view's binding's scope first.", tier: "advanced", phase: "analyses", help: "A view reads its source for as long as it lives. Finish with the view before changing the source.", span: "The modification: the place assigned, the argument passed `inout`, or the receiver taken by `inout self`.", retired: false, examples: &[Example { wrong: "use std.view\n\nfn main() / io {\n  var xs = [1, 2, 3]\n  let v = view.View.all(xs)\n  print(\"{v.len()}\")\n  xs.push(4)\n  print(\"{xs.len()}\")\n}\n", line: 7, right: "use std.view\n\nfn main() / io {\n  var xs = [1, 2, 3]\n  print(\"{view.View.all(xs).len()}\")\n  xs.push(4)\n  print(\"{xs.len()}\")\n}\n" }] });
/// a projection yields exactly once
pub const E0424: Code = Code(&Entry { code: "E0424", title: "a projection yields exactly once", reference: "projections.once-on-every-path", rule: "Every path through a projection's body from its start to its end or to a `return` runs exactly one `yield`. A path that ends by raising or panicking runs at most one. Breaking this is E0424, a projection yields exactly once, at one of these places:\n- a `yield` inside a `loop`, `while` or `for` body, which then counts as the one `yield` of the paths through the loop;\n- a `yield` inside the operand of a `try` that has `catch` arms, which then counts as the one `yield` of the paths through it;\n- the second `yield` of a path;\n- for a path without one, the end of the body, its closing brace, or the `return` the path reaches.\nThe check is syntactic, as the law of exclusivity is. The paths through the arms of an `if`, a `match` or a `catch` are followed one by one, and an arm whose type is `Never` ends its paths.", tier: "advanced", phase: "analyses", help: "A projection hands its caller one place on every path. Yield on each path, or raise or panic on the others.", span: "The `yield` inside a loop, the second `yield` of a path, or the end of the body or the `return` that a path reaches without one.", retired: false, examples: &[Example { wrong: "fn at(inout xs: List<i64>, i: i64) -> inout i64 {\n  if i < xs.len() {\n    yield xs[i]\n  }\n}\n", line: 5, right: "fn at(inout xs: List<i64>, i: i64) -> inout i64 {\n  yield xs[i]\n}\n" }] });
/// `yield` outside a projection
pub const E0425: Code = Code(&Entry { code: "E0425", title: "`yield` outside a projection", reference: "projections.yield", rule: "`yield e` is a statement, allowed only in the body of a projection. In any other function's body, in a closure literal, a test, a constant or a doc example, it is E0425, `yield` outside a projection. Its operand is one of these:\n- a place rooted in a `var` binding or an `inout` parameter of the body, of the projection's type `T`;\n- an expression of a view type that isn't a place, which is bound by `var` to a temporary of the statement and yielded as that place (projections.writable-bindings).\nAny other operand is E0401, and a place rooted in a `let` binding is E0403 (modes.what-can-be-modified). The operand's index expressions are evaluated when the statement runs, and the place is then handed to the caller. A `yield` whose place goes through an index allocates, as an `inout` argument's does (facts.allocation), and yielding a binding is where it escapes (modes.escaping). A projection's body has type `()`: its block's final expression, if any, is `()`, and a `return` in it takes no value.", tier: "advanced", phase: "types", help: "`yield` hands a place to the caller, which only a projection, a function whose result is written `inout T`, does. Write the result as `-> inout T`, or return a value.", span: "The `yield`.", retired: false, examples: &[Example { wrong: "fn first(inout xs: List<i64>) {\n  yield xs[0]\n}\n", line: 2, right: "fn first(inout xs: List<i64>) -> inout i64 {\n  yield xs[0]\n}\n" }] });
/// a projection isn't a value
pub const E0426: Code = Code(&Entry { code: "E0426", title: "a projection isn't a value", reference: "projections.not-a-value", rule: "A projection named other than to call it, as a value, an argument or a stored function, is E0426, a projection isn't a value, at the name. A projection has no function type.", tier: "advanced", phase: "types", help: "A projection's call is a place, not a value, so it can only be called. Call it where you use it.", span: "The projection's name, where it is used other than to call it.", retired: false, examples: &[Example { wrong: "fn at(inout xs: List<i64>, i: i64) -> inout i64 {\n  yield xs[i]\n}\n\nfn main() / io {\n  var xs = [1, 2]\n  let cell = at\n  cell(inout xs, 0) = 3\n  print(\"{xs}\")\n}\n", line: 7, right: "fn at(inout xs: List<i64>, i: i64) -> inout i64 {\n  yield xs[i]\n}\n\nfn main() / io {\n  var xs = [1, 2]\n  at(inout xs, 0) = 3\n  print(\"{xs}\")\n}\n" }] });
/// a projection can't raise
pub const E0427: Code = Code(&Entry { code: "E0427", title: "a projection can't raise", reference: "projections.cannot-raise", rule: "A projection's row holds no `raise<E>`: `raise<E>` in it is E0427, a projection can't raise, at the element. A call that is a place can't sit in the operand of a `try` (effects.marking). A `raise` in the body is then E0502, as in any function whose row lacks it (effects.inference).", tier: "advanced", phase: "items", help: "A projection's call is a place, which `try` can't mark, so a projection can't raise. Check before calling it, or panic on a bad index.", span: "The `raise<E>` element of the projection's row.", retired: false, examples: &[Example { wrong: "type OutOfRange = | OutOfRange\n\nfn at(inout xs: List<i64>, i: i64) -> inout i64 / raise<OutOfRange> {\n  yield xs[i]\n}\n", line: 3, right: "fn at(inout xs: List<i64>, i: i64) -> inout i64 {\n  yield xs[i]\n}\n" }] });
/// a view reads what it must write
pub const E0428: Code = Code(&Entry { code: "E0428", title: "a view reads what it must write", reference: "projections.writable-bindings", rule: "A `var` binding of type `View<T>`, and an `inout` parameter of type `View<T>`, are writable. A binding of `Option<View<T>>` reads, as other bindings do, since no place goes through an `Option`. The view given to a `var` binding, as its value or assigned to the whole of it, must write every source it has. Given to a `var` binding or to the `var` of a `yield` (projections.yield), a view that reads a source is E0428, a view reads what it must write. The error is at the view, and names the source. The error offers two fixes: make the view with `view.into(inout xs, …)`, or bind it with `let`. An `inout` argument is a place, so it is a writable binding already, which writes itself inside the callee.", tier: "advanced", phase: "analyses", help: "A view that the code writes through is made writable, with `view.into(inout xs, …)`.", span: "The view given to the `var` binding, yielded or returned.", retired: false, examples: &[Example { wrong: "use std.view\n\nfn main() / io {\n  var xs = [1, 2, 3]\n  var head = view.View.of(xs, 0, 2)\n  head[0] = 9\n  print(\"{head}\")\n}\n", line: 5, right: "use std.view\n\nfn main() / io {\n  var xs = [1, 2, 3]\n  var head = view.into(inout xs, 0, 2)\n  head[0] = 9\n  print(\"{head}\")\n}\n" }] });
/// reaching a value while a view writes it
pub const E0429: Code = Code(&Entry { code: "E0429", title: "reaching a value while a view writes it", reference: "projections.reaching-written-source", rule: "While a writable binding writes a source, any access to a place that overlaps the source is E0429, reaching a value while a view writes it, at the access. A read is such an access too. This is the law of exclusivity, applied to the binding's write. The error names the view and the line where its write ends. It is counted as E0404 is (modes.change-while-iterating). The error offers two fixes: reach the value before the view, or end the view's binding's scope first.", tier: "advanced", phase: "analyses", help: "While a view writes its source, the source is the view's. Use the view, or let it end before reading the source.", span: "The access: the place read, assigned or passed, or the receiver of a method.", retired: false, examples: &[Example { wrong: "use std.view\n\nfn main() / io {\n  var xs = [1, 2, 3]\n  var head = view.into(inout xs, 0, 2)\n  head[0] = 9\n  print(\"{xs.len()}\")\n}\n", line: 7, right: "use std.view\n\nfn main() / io {\n  var xs = [1, 2, 3]\n  var head = view.into(inout xs, 0, 2)\n  head[0] = 9\n  print(\"{head.len()}\")\n}\n" }] });
/// `when` inside a `when`
pub const E0430: Code = Code(&Entry { code: "E0430", title: "`when` inside a `when`", reference: "shared.locks", rule: "Running a `when` gives a function the inferred fact `locks`, which is inferred as the implicit effects are (facts.inference). A `when` is a site of it, and so is a call of a function that has it, or a use of one as a value. A call through a function value adds nothing (facts.calls-through-function-values), and a closure literal's body is part of the function that writes it.\nA `when` whose block holds a site of `locks` is a `when` inside a `when` (E0430), at the site. `locks` is a limit of a `without` clause and a contextual keyword (facts.without, facts.spelling). So `without locks` promises that the code holds no `Shared<T>`, with E0204 at each site. `stilt show` prints `locks` in a function's bracket of facts (facts.visibility).", tier: "advanced", phase: "analyses", help: "Holding one shared value while waiting for another could deadlock. Hold both in one `when`, as `when a, b { … }`.", span: "The inner `when`, or the call of a function that has `locks`.", retired: false, examples: &[Example { wrong: "use std.sync\n\ntype Account = { balance: i64 }\n\nfn moved(a: sync.Shared<Account>, b: sync.Shared<Account>, n: i64) {\n  when a {\n    a.balance -= n\n    when b { b.balance += n }\n  }\n}\n", line: 8, right: "use std.sync\n\ntype Account = { balance: i64 }\n\nfn moved(a: sync.Shared<Account>, b: sync.Shared<Account>, n: i64) {\n  when a, b {\n    a.balance -= n\n    b.balance += n\n  }\n}\n" }] });
/// closure that can't run in parallel
pub const E0431: Code = Code(&Entry { code: "E0431", title: "closure that can't run in parallel", reference: "par.what-runs-in-parallel", rule: "Each parameter of a function of `std.par` that takes a function is `escaping` with no row (effects.escaping-parameters). So its argument performs no effect, `io` and `raise` included, and the call passes none through. A closure literal whose body prints or raises is E0502 there (effects.inference), and a named function whose row isn't empty is a type mismatch (E0311).\nThe argument must also be `calm` and `portable` (modes.demands). One that reaches a `Shared<T>` or a view is a closure that can't run in parallel (E0431), at the argument. The error has one note, at the binding that gave it the mode (modes.diagnostic-shape). So no program can tell how many threads ran a call.", tier: "advanced", phase: "analyses", help: "`std.par` runs the closure on other threads, so it can't reach a `Shared` value. Read the shared value once before the call, and capture the copy.", span: "The argument.", retired: false, examples: &[Example { wrong: "use std.par\nuse std.sync\n\nfn scaled(factor: sync.Shared<i64>, xs: List<i64>) -> List<i64> {\n  par.map(xs, |x| when factor { factor * x })\n}\n", line: 5, right: "use std.par\nuse std.sync\n\nfn scaled(factor: sync.Shared<i64>, xs: List<i64>) -> List<i64> {\n  let f = when factor { factor }\n  par.map(xs, |x| f * x)\n}\n" }] });
/// value that can't reach another task
pub const E0432: Code = Code(&Entry { code: "E0432", title: "value that can't reach another task", reference: "shared.tasks-and-modes", rule: "A value that reaches another task must be `portable` (modes.fixed-values, modes.demands). Such a value is the value given to `Shared.new`, or a task's function, given to `task.spawn` or to `s.spawn`.\nA `fixed` value given to `Shared.new`, as a view is, is a value that can't reach another task (E0432), at the value. So is a task's function that captures a `fixed` binding, at the capture. Each has one note, at the binding that gave it the mode (modes.diagnostic-shape). A `Shared<T>` is `portable` and `contended` (modes.contended-values), so a task captures handles freely.", tier: "advanced", phase: "analyses", help: "A view can't reach another task, since it must not outlive its source. Capture the value it views.", span: "The value given to `Shared.new`, or the capture of the task's function.", retired: false, examples: &[Example { wrong: "use std.task\nuse std.view\n\nfn counted(xs: List<i64>) -> i64 / async {\n  let v = view.View.all(xs)\n  task.spawn(|| v.len()).await()\n}\n", line: 6, right: "use std.task\n\nfn counted(xs: List<i64>) -> i64 / async {\n  task.spawn(|| xs.len()).await()\n}\n" }] });
/// `when` on something that isn't shared
pub const E0433: Code = Code(&Entry { code: "E0433", title: "`when` on something that isn't shared", reference: "shared.when", rule: "`when a, b { block }` (a `primary`, syntax.expressions) names one or more bindings, locals or parameters, whose types are `Shared<T>`. Any other name or type, and a name given twice, is a `when` on something that isn't shared (E0433).\nThe `when` waits until it holds every value that its handles reach, then runs `block`, and then releases the values. In `block`, each name stands for the place of its handle's value, of type `T`, readable and writable as a `var` is (modes.what-can-be-modified). Each value keeps what its place holds when the block ends, however it ends. The `when`'s value is the block's.\nInside the block, a name stands for a `T`, not a handle, so a `when` there that names it is E0433. Two names whose handles reach one value are one place: a write through one is read through the other (shared.names-that-may-be-one-place).", tier: "advanced", phase: "types", help: "`when` holds shared values, of type `Shared<T>`. Use an ordinary value directly.", span: "The name.", retired: false, examples: &[Example { wrong: "fn bumped(n: i64) -> i64 {\n  when n { n + 1 }\n}\n", line: 2, right: "fn bumped(n: i64) -> i64 {\n  n + 1\n}\n" }] });
/// scope that escapes
pub const E0434: Code = Code(&Entry { code: "E0434", title: "scope that escapes", reference: "tasks.scope-that-escapes", rule: "A binding of type `Scope<E>` is used only as the receiver of `spawn` or as an argument given to a parameter of type `Scope<E>`. Any other use, a capture in a task's function included, is a scope that escapes (E0434), at the first such use in source order. So a scope never outlives the call of `task.scope` that made it. The check is the one for a non-escaping parameter (effects.no-escape), with a parameter of type `Scope<E>` among the places a scope may go.", tier: "advanced", phase: "analyses", help: "A scope ends when its `task.scope` call returns, so it is used there to start tasks, as `s.spawn(f)`, and never kept or captured by a task.", span: "The first use that keeps the scope: its name, or the closure literal that names it.", retired: false, examples: &[Example { wrong: "use std.task\n\nfn started() -> i64 / {io, async, raise<str>} {\n  try task.scope(|s| {\n    let t = try s.spawn(|| try s.spawn(|| 1).await())\n    t.await()\n  })\n}\n", line: 5, right: "use std.task\n\nfn started() -> i64 / {io, async, raise<str>} {\n  try task.scope(|s| {\n    let t = try s.spawn(|| 1)\n    t.await()\n  })\n}\n" }] });
/// `when` in a lazy value's function
pub const E0435: Code = Code(&Entry { code: "E0435", title: "`when` in a lazy value's function", reference: "polymorphism.lazy-waits-for-nothing", rule: "`f` waits for nothing. A site of `locks` (shared.locks) in either of these is E0435, `when` in a lazy value's function, at the site, unless E0430 reports it:\n- the closure literal or function given to `new`;\n- the closure literal that a `let` binds to the local given to `new`.\nA `when` that runs while an `f` runs panics with the kind `deadlock` before it holds anything (shared.when-on-value-already-held). This holds for a `when` on the thread of `f`, and in a part of a call of `std.par` that `f` makes (par.std-par). It holds too for a `when` that `f` reaches through a function value, which no check sees. So `f` never waits for the code that asked for its value. It never reaches the `Lazy` it computes, which only a shared value could hold (cycles.through-shared-values).", tier: "advanced", phase: "analyses", help: "A `Lazy` computes its value whenever it is first asked for, so its function must not wait for shared values. Read them before, and capture the copy.", span: "The `when`, or the call of a function that has `locks`, inside the function that `Lazy.new` keeps.", retired: false, examples: &[Example { wrong: "use std.sync\nuse std.lazy\n\ntype Rates = { euro: f64 }\n\nfn priced(rates: sync.Shared<Rates>, amount: f64) -> lazy.Lazy<f64> {\n  lazy.Lazy.new(|| when rates { amount * rates.euro })\n}\n", line: 7, right: "use std.sync\nuse std.lazy\n\ntype Rates = { euro: f64 }\n\nfn priced(rates: sync.Shared<Rates>, amount: f64) -> lazy.Lazy<f64> {\n  let euro = when rates { rates.euro }\n  lazy.Lazy.new(|| amount * euro)\n}\n" }] });
/// unsafe operation outside `unsafe`
pub const E0436: Code = Code(&Entry { code: "E0436", title: "unsafe operation outside `unsafe`", reference: "c.unsafe-operations", rule: "These operations are unsafe. They stand only inside an `unsafe` block, or they are E0436, unsafe operation outside `unsafe`, at the call, or at the name of a function used as a value:\n- a call of a foreign function, or a use of one as a value;\n- `p.read()`, `p.write(v)` and `p.read_list(n)` on a `c.Ptr<T>`, which read or write `T`s at its address, and a use of one of these as a value;\n- `s.to_str()` on a `c.Str`, which copies its bytes up to the NUL, and a use of it as a value.\nTest bodies and doc examples are code like any other: an unsafe operation in one needs a block too. This is part of the systems tier.", tier: "systems", phase: "types", help: "Calling C, or reading through a pointer, can break every guarantee Stilt makes, so it stands inside `unsafe because \"…\" { … }`, whose reason says why the code is sound.", span: "The call, or the name of the function used as a value.", retired: false, examples: &[Example { wrong: "use std.c\n\nextern fn strlen(s: c.Str) -> u64\n\npub fn length(text: str) -> u64 {\n  text.with_c_str(|s| strlen(s))\n}\n", line: 6, right: "use std.c\n\nextern fn strlen(s: c.Str) -> u64\n\npub fn length(text: str) -> u64 {\n  unsafe because \"with_c_str ends s with a NUL\" { text.with_c_str(|s| strlen(s)) }\n}\n" }] });
/// `unsafe` with no reason
pub const E0437: Code = Code(&Entry { code: "E0437", title: "`unsafe` with no reason", reference: "c.unsafe-because", rule: "`unsafe because \"reason\" { … }` is a block expression, whose value is its block's (the `primary` production, syntax.expressions). The reason is a string literal with no interpolation and at least one character that isn't whitespace (lexical.whitespace). A reason with no such character is E0437, `unsafe` with no reason, at the reason. `unsafe` without `because` is E0100, syntax error. Like a block, the form stands in no head (expressions.heads). `because` there is a contextual keyword (lexical.contextual-keywords), and `parse --sexp` prints the form as `(unsafe \"reason\" BLOCK)`. A closure literal inside the block is inside it, so the closure given to `with_ptr` may call a foreign function. So is a block inside it: `unsafe` blocks nest. This is part of the systems tier.", tier: "systems", phase: "types", help: "An `unsafe` block's reason says why its code is sound, and `stilt show` prints it beside the block. Write the reason.", span: "The reason.", retired: false, examples: &[Example { wrong: "use std.c\n\nextern fn strlen(s: c.Str) -> u64\n\npub fn length(text: str) -> u64 {\n  unsafe because \" \" { text.with_c_str(|s| strlen(s)) }\n}\n", line: 6, right: "use std.c\n\nextern fn strlen(s: c.Str) -> u64\n\npub fn length(text: str) -> u64 {\n  unsafe because \"with_c_str ends s with a NUL\" { text.with_c_str(|s| strlen(s)) }\n}\n" }] });

